const READING = [
  {id:'r1', lv:'Pendek', kind:'Pengumuman', title:'図書館からのお知らせ',
   paras:['来月5日から10日まで、図書館は蔵書整理のため休館します。期間中は貸出・返却ができませんので、ご注意ください。返却期限が休館中に来る本は、11日以降にお持ちいただければ延滞料金はかかりません。なお、電子書籍サービスは通常どおりご利用いただけます。'],
   qs:[
     {q:'このお知らせの内容は何ですか。', opts:['図書館が一時的に休館すること','図書館が新しく建て替えられること','延滞料金が上がること','電子書籍サービスが始まること'], a:0, type:'mainidea', d:'Ide utama: pemberitahuan penutupan sementara perpustakaan untuk penataan koleksi.'},
     {q:'休館中に返却期限が来る本はどうすればよいですか。', opts:['急いで休館前に返しに行く','<ruby>罰金<rt>ばっきん</rt></ruby>を電話で払う','11日以降に持って行けば延滞料金はかからない','返却はできない'], a:2, type:'detail', d:'Detail teks: buku yang jatuh tempo saat tutup bisa dikembalikan mulai tanggal 11 tanpa denda.'},
     {q:'休館中でも使えるものはどれですか。', opts:['貸出カウンター','返却ボックス','閲覧室','電子書籍サービス'], a:3, type:'detail', d:'Teks menyebut layanan e-book tetap berjalan seperti biasa.'},
   ]},
  {id:'r2', lv:'Pendek', kind:'Email', title:'メール：会議時間の変更',
   paras:['鈴木様 お疲れ様です。山田です。来週火曜日の定例会議ですが、クライアントとの打ち合わせが長引く見込みのため、開始時間を午後2時から3時に変更させていただけないでしょうか。場所は変わりません。資料は前日までにメールでお送りします。ご都合が悪ければご連絡ください。'],
   qs:[
     {q:'このメールの目的は何ですか。', opts:['会議をキャンセルすること','資料を早くもらうこと','会議の開始時間を変更したいこと','打ち合わせの場所を変えること'], a:2, type:'tujuan', d:'Tujuan penulis: meminta perubahan jam mulai rapat dari pukul 2 ke pukul 3 sore.'},
     {q:'会議の開始が遅れる理由は何ですか。', opts:['山田が休むから','資料がまだできていないから','クライアントとの打ち合わせが長くなりそうだから','会議室が使えないから'], a:2, type:'alasan', d:'Alasannya: rapat dengan klien diperkirakan molor (長引く見込み).'},
     {q:'鈴木さんが都合が悪い場合、どうすべきですか。', opts:['直接会社に行く','連絡する','返事は不要','資料を待つ'], a:1, type:'detail', d:'Kalimat terakhir: ご都合が悪ければご連絡ください — hubungi jika tidak berkenan.'},
   ]},
  {id:'r3', lv:'Sedang', kind:'Artikel pendek', title:'リモートワークの広がり',
   paras:['ここ数年、リモートワークを導入する企業が増えている。通勤時間が不要になり、多くの人が時間を有効に使えるようになった。',
          '一方で、同僚と直接顔を合わせる機会が減り、孤独感を<ruby>訴える<rt>うったえる</rt></ruby>人も少なくない。ある調査では、週に一度は出社したいと答えた人が全体の六割に上った。',
          '企業は、完全なリモートか、週数日の出社を組み合わせるか、働き方の選択肢を増やすことが求められている。'],
   qs:[
     {q:'この文章のテーマは何ですか。', opts:['リモートワークの歴史','通勤時間の減らし方','リモートワークの利点と<ruby>課題<rt>かだい</rt></ruby>','調査のやり方'], a:2, type:'mainidea', d:'Ide utama: kelebihan (efisiensi waktu) dan tantangan (kesepian) kerja remote.'},
     {q:'調査で六割の人が望んだことは何ですか。', opts:['完全なリモートワーク','給料アップ','週に一度は出社すること','転職'], a:2, type:'detail', d:'Detail: 週に一度は出社したい人が六割.'},
     {q:'筆者が企業に望んでいることは何ですか。', opts:['働き方の選択肢を増やすこと','リモートを完全にやめること','出社を<ruby>義務<rt>ぎむ</rt></ruby>化すること','調査を続けること'], a:0, type:'infer', d:'Inferensi dari paragraf terakhir: perusahaan dituntut menambah pilihan cara kerja.'},
     {q:'「少なくない」はどういう意味ですか。', opts:['ほとんどいない','かなり多い','全員','誰もいない'], a:1, type:'kata', d:'少なくない dalam konteks = tidak sedikit → cukup banyak.'},
   ]},
  {id:'r4', lv:'Sedang', kind:'Opini', title:'スマホ時代の読書',
   paras:['スマートフォンの普及で、本を読む時間が減ったとよく言われる。確かに、電車の中で新聞や本を開く人は以前より少なくなった。',
          'しかし、私は読書が消えたのではなく、形を変えただけだと考える。電子書籍やSNSの文章も、立派な読書体験である。問題は量ではなく、深く考えながら読むかどうかだ。',
          '大切なのは、短い文を流し読みするだけでなく、時には長い文章にじっくり向き合う時間を持つことではないだろうか。'],
   qs:[
     {q:'筆者の主張はどれですか。', opts:['SNSは読書ではない','スマホは悪いので使うべきではない','電車では本を読むべきだ','読書は形を変えて続いており、深く読むことが大切'], a:3, type:'mainidea', d:'Main idea: membaca tidak hilang, hanya berubah bentuk; yang penting membaca dengan mendalam.'},
     {q:'筆者が「形を変えただけ」と言う理由は何ですか。', opts:['紙の本がもうないから','電子書籍やSNSの文章も読書体験だから','読書量が増えたから','新聞が人気だから'], a:1, type:'alasan', d:'Alasan: e-book dan tulisan SNS juga merupakan pengalaman membaca yang layak.'},
     {q:'「じっくり向き合う」に近い意味はどれですか。', opts:['集中して読むこと','速く読むこと','声に出して読むこと','飛ばして読むこと'], a:0, type:'kata', d:'じっくり向き合う = menghadapi dengan sungguh-sungguh → membaca dengan fokus.'},
     {q:'最後の段落で筆者が勧めていることは何ですか。', opts:['毎日新聞を読むこと','長い文章にも時間をかけて向き合うこと','スマホを捨てること','短文だけを読むこと'], a:1, type:'tujuan', d:'Tujuan akhir: sesekali luangkan waktu untuk menghadapi teks panjang dengan serius.'},
   ]},
  {id:'r5', lv:'N2', kind:'Penjelasan abstrak', title:'日本語の「曖昧さ」',
   paras:['日本語はよく「曖昧な言語だ」と言われる。<ruby>断定<rt>だんてい</rt></ruby>的な表現を避け、「〜と思う」「〜かもしれない」と柔らかく言い換える傾向が確かに存在する。',
          'しかし、この<ruby>曖昧<rt>あいまい</rt></ruby>さは日本語の欠点ではない。相手の立場に配慮し、対立を<ruby>避ける<rt>さける</rt></ruby>ためのコミュニケーションの<ruby>工夫<rt>くふう</rt></ruby>だと考えるべきだろう。はっきり言うことが常に正しいとは限らないからだ。',
          'もちろん、<ruby>曖昧<rt>あいまい</rt></ruby>さには弊害もある。<ruby>責任<rt>せきにん</rt></ruby>の所在が不明確になり、ビジネスや国際交流で<ruby>誤解<rt>ごかい</rt></ruby>を生むことがある。重要なのは、場面に応じて<ruby>曖昧<rt>あいまい</rt></ruby>さと明確さを使い分ける力である。'],
   qs:[
     {q:'この文章で筆者が最も伝えたいことは何ですか。', opts:['日本語は<ruby>曖昧<rt>あいまい</rt></ruby>すぎる','<ruby>曖昧<rt>あいまい</rt></ruby>さは欠点であり直すべきだ','<ruby>曖昧<rt>あいまい</rt></ruby>さの功罪を理解し使い分けることが重要だ','明確に話す練習をすべきだ'], a:2, type:'mainidea', d:'Main idea: penting memahami kelebihan-kekurangan kesamaran dan memakainya sesuai situasi.'},
     {q:'筆者によると、<ruby>曖昧<rt>あいまい</rt></ruby>さの背景にあるものは何ですか。', opts:['文法の弱さ','教育の問題','漢字の多さ','相手への配慮と対立の<ruby>回避<rt>かいひ</rt></ruby>'], a:3, type:'alasan', d:'Alasan versi penulis: kesamaran lahir dari kepedulian pada posisi lawan bicara dan menghindari konflik.'},
     {q:'<ruby>曖昧<rt>あいまい</rt></ruby>さの弊害として挙げられているものはどれですか。', opts:['会話が長くなる','<ruby>責任<rt>せきにん</rt></ruby>の所在が不明確になる','敬語が使えなくなる','文が書けなくなる'], a:1, type:'detail', d:'Detail paragraf 3: letak tanggung jawab jadi tidak jelas dan memicu salah paham.'},
     {q:'「使い分ける力」とは何ですか。', opts:['早口で話す力','二か国語を話す力','<ruby>曖昧<rt>あいまい</rt></ruby>にだけ話す力','状況に応じて表現の明確さを調整する力'], a:3, type:'infer', d:'Inferensi: kemampuan mengatur tingkat kejelasan sesuai situasi.'},
   ]},
  {id:'r6', lv:'N2', kind:'Argumentasi', title:'AIと語学学習',
   paras:['AI翻訳の精度が上がり、「もう外国語を学ぶ必要はない」という声を聞くことが増えた。確かに、旅行や簡単な連絡なら、翻訳アプリで十分かもしれない。',
          'だが、言語を学ぶ意義は翻訳のためだけではない。外国語を学ぶ過程で、私たちは異なる文化や考え方に触れ、自国の言語をも客観的に見つめ直すことができる。',
          'むしろAI時代だからこそ、機械に任せられる部分と、人間が自ら学ぶべき部分を見極める力が求められるのだ。'],
   qs:[
     {q:'筆者の考えに最も近いものはどれですか。', opts:['AIの利点を認めつつも、語学学習の意義は残る','AIがあれば翻訳は完璧だ','語学学習はもう不要だ','翻訳アプリは使うべきではない'], a:0, type:'mainidea', d:'Main idea: AI berguna, tapi makna belajar bahasa tetap ada.'},
     {q:'語学学習の意義として筆者が挙げていないものはどれですか。', opts:['異なる考え方に触れられる','自国の言語を見直せる','翻訳の仕事が増える','異文化に触れられる'], a:2, type:'detail', d:'Yang TIDAK disebut: bertambahnya pekerjaan penerjemah.'},
     {q:'「見極める」に近い意味はどれですか。', opts:['見分けて判断する','見上げる','見逃す','じっと見つめる'], a:0, type:'kata', d:'見極める = membedakan dan menilai → 見分けて判断する.'},
     {q:'筆者が読者に求めている態度はどれですか。', opts:['AIを全面的に<ruby>拒否<rt>きょひ</rt></ruby>する','すべて自分で翻訳する','便利な部分はAIに任せ、学ぶべき部分は自分で学ぶ','外国語の勉強をやめる'], a:2, type:'tujuan', d:'Tujuan penulis: gunakan AI untuk bagian yang bisa diserahkan mesin, pelajari sendiri sisanya.'},
   ]},
  {id:'r7', lv:'N2', kind:'統合理解 (A/B)', title:'リモートワークの是非', src:'rbnhd/jlpt-n2-reading #005',
   paras:['【文章A】<br>リモートワークは現代の理想的な働き方だと言える。まず、通勤時間がなくなることで、その時間を家族や趣味、自己啓発に有効に使える。片道1時間の通勤であれば、1日2時間、週に10時間もの時間が節約できる計算だ。また、自分のペースで仕事ができるため、生産性も大幅に向上する。会議もオンラインで効率的に行え、移動時間や会議室の準備といった無駄な時間が削減される。さらに、家族との時間も増え、ワークライフバランスが大きく改善される。育児や介護と仕事の両立も可能になり、特に子育て世代や介護を抱える社員にとっては大きなメリットとなる。これからの時代、リモートワークは標準的な働き方になるべきだろう。企業側も、オフィス維持費の削減や優秀な人材の確保といったメリットを享受できる。',
          '【文章B】<br>リモートワークには見過ごせない多くの課題がある。まず、直接会って話すことで生まれる創造的なアイデアや、偶然の出会いから生まれる新しい発想が失われてしまう。オンライン会議では、細かいニュアンスや雰囲気を読み取ることが難しい。また、新入社員の教育も深刻な問題だ。先輩の仕事を見て学ぶ機会がなくなり、技術の伝承が困難になる。成長が遅れ、キャリア形成に支障をきたす可能性もある。さらに、仕事とプライベートの境界が曖昧になり、かえって長時間労働につながったり、ストレスが増える人も少なくない。やはり、対面でのコミュニケーションは欠かせないものであり、完全なリモートワークには慎重であるべきだ。'],
   qs:[
     {q:'文章AとBの筆者が共通して認識している点は何か。', opts:['新入社員教育は簡単になる','リモートワークは働き方に大きな変化をもたらす','対面コミュニケーションは不要である','リモートワークは生産性を向上させる'], a:1, type:'togou', d:'両者とも、リモートワークが働き方に大きな影響を与えることは認識していますが、その評価が異なります。'},
     {q:'文章Bの筆者が最も懸念していることは何か。', opts:['創造性や人材育成の機会が失われること','会議の効率が悪くなること','通勤時間が長くなること','家族との時間が減ること'], a:0, type:'detail', d:'文章Bでは、創造的なアイデアの喪失と新入社員教育の困難さ、技術伝承の問題を主要な課題として挙げています。'},
   ]},
  {id:'r8', lv:'N2', kind:'統合理解 (A/B)', title:'「失敗」から学ぶこと', src:'rbnhd/jlpt-n2-reading #023',
   paras:['【文章A：リスク管理の観点から】<br>失敗は可能な限り避けるべきものだ。現代の競争社会では成功こそが評価され、失敗は恥や無能の証とされがちである。だからこそ、失敗しないように慎重に計画を立て、リスクを分析し、着実に行動することが何より大切である。',
          '特にビジネスの世界では、一度の大きな失敗が会社に取り返しのつかない損失をもたらすこともある。新製品の開発に失敗すれば巨額の投資が無駄になり、顧客の信頼を失えば回復に何年もかかる。優秀なリーダーとは、リスクを最小限に抑え、確実に成功する方法を選択できる人物だ。過去のデータを分析し、成功事例を学び、失敗の可能性を徹底的に排除する。失敗を恐れることは、決して悪いことではない。それは責任感の表れであり、組織を守るために必要な慎重さなのである。無謀な挑戦よりも、確実な成功を積み重ねることこそが、長期的な発展につながる。',
          '【文章B：成長の機会として】<br>失敗は成長の糧であり、むしろ積極的に経験すべきものだ。多くの成功者が、自身の最大の失敗から学んだ教訓について熱く語っている。スティーブ・ジョブズは一度アップル社を追われたが、その経験が後の偉大な成功の礎となった。失敗を恐れて何も行動しなければ、成長の貴重な機会を永遠に失ってしまう。',
          '新しいことに勇気を持って挑戦し、たとえ失敗しても、そこから教訓を得て次に活かすことが何より重要だ。失敗を通じて初めて、自分の弱点や改善点、思考の癖が明確に見えてくる。成功からは学べないことを、失敗は教えてくれるのだ。',
          'むしろ、若いうちに多くの小さな失敗を経験することで、将来の致命的な大きな失敗を避けられるのではないだろうか。失敗のコストが比較的小さい段階で試行錯誤を重ね、学ぶ。それが真の成長につながる。失敗を恐れない勇気と、失敗から学ぶ謙虚さこそが、イノベーションを生み出す原動力となり、個人の可能性を最大限に引き出すのである。完璧を目指して何もしないよりも、不完全でも行動し、改善し続けることの方がはるかに価値がある。'],
   qs:[
     {q:'文章Aと文章Bの共通点は何か。', opts:['失敗について考えることは重要だ','失敗は絶対に避けるべきだ','失敗から学ぶことはできない','成功者は失敗しない'], a:0, type:'togou', d:'両者とも失敗について異なる視点から論じており、失敗について考えることの重要性を示唆しています。'},
     {q:'文章Bの筆者が失敗について述べていることとして正しいのはどれか。', opts:['失敗は責任感の欠如だ','失敗から学ぶことで成長できる','失敗は恥である','失敗を避けることが最も重要だ'], a:1, type:'detail', d:'文章Bでは「失敗は成長の糧である」と述べ、失敗から学ぶことの重要性を強調しています。'},
   ]},
  {id:'r9', lv:'N2', kind:'主張理解・長文', title:'睡眠と健康の関係', src:'rbnhd/jlpt-n2-reading #007',
   paras:['現代社会において、睡眠不足は深刻な問題となっている。日本人の平均睡眠時間は先進国の中でも特に短く、成人の約4割が6時間未満の睡眠しか取っていないという調査結果がある。2019年のOECDの調査によれば、日本人の平均睡眠時間は7時間22分で、加盟国33カ国中最も短い。特に働き盛りの30代から40代においては、5時間台という人も珍しくない。長時間労働や通勤時間の長さ、夜型のライフスタイルなどが、この睡眠不足の背景にある。',
          '睡眠不足がもたらす影響は、単に日中の眠気だけではない。集中力の低下により仕事のミスが増え、生産性が下がる。アメリカの研究では、睡眠不足による経済損失は年間約4000億ドルにも上るという報告がある。また、免疫力が低下し、風邪やインフルエンザなどの感染症にかかりやすくなる。さらに深刻なのは、慢性的な睡眠不足が生活習慣病のリスクを高めることだ。糖尿病や高血圧、心臓病、肥満などの発症率が、睡眠不足の人では明らかに高いことが複数の研究で示されている。特に、睡眠時間が5時間未満の場合、糖尿病のリスクは約2.5倍に、心筋梗塞のリスクは約2倍に増加すると言われている。',
          '精神面への影響も無視できない。睡眠不足はストレスホルモンであるコルチゾールの分泌を増加させ、ストレスを増大させる。その結果、うつ病や不安障害のリスクを高める。十分な睡眠は、脳が日中に獲得した情報を整理し、記憶を定着させ、感情を安定させるために不可欠なのだ。レム睡眠中には感情記憶の処理が行われ、ノンレム睡眠中には新しい情報が長期記憶として定着する。',
          'では、理想的な睡眠時間はどのくらいだろうか。個人差はあるものの、一般的に成人は7〜8時間の睡眠が推奨されている。しかし、単に時間を確保すればよいわけではない。睡眠の質も重要だ。深い睡眠であるノンレム睡眠の第3段階、第4段階を十分に取ることが、心身の回復には欠かせない。',
          '睡眠の質を高めるためには、規則正しい生活リズムを保つことが大切だ。毎日同じ時間に寝起きすることで、体内時計が整う。また、寝る前のスマートフォンやパソコンの使用を控える。これらの機器から発せられるブルーライトは、睡眠ホルモンであるメラトニンの分泌を抑制してしまうからだ。さらに、日中の適度な運動と、就寝前のカフェインやアルコールの摂取を控えることも効果的だ。寝室の環境も重要で、暗く静かで、温度は16〜19度が理想的とされている。',
          '現代人にとって、十分な睡眠を確保することは容易ではない。仕事の締め切り、家事、育児、さまざまな社会活動など、時間を奪う要因は数多い。しかし、睡眠を軽視することの代償は大きい。健康的な生活を送るために、睡眠の重要性を再認識し、意識的に睡眠時間を確保する努力が必要である。「睡眠は最高の投資」という認識を持ち、自分の健康を第一に考える生活習慣を築いていくべきだ。'],
   qs:[
     {q:'睡眠不足がもたらす影響として述べられていないものはどれか。', opts:['生産性の低下','生活習慣病のリスク増加','免疫力の低下','記憶力の向上'], a:3, type:'detail', d:'記憶力の向上は述べられていません。むしろ集中力の低下が指摘されています。'},
     {q:'睡眠の質を高める方法として挙げられていないものはどれか。', opts:['寝る前の読書','適度な運動','規則正しい生活リズム','カフェインを控える'], a:0, type:'detail', d:'寝る前の読書については言及されていません。スマートフォンの使用を控えることは述べられています。'},
     {q:'筆者の主張として最も適切なものはどれか。', opts:['睡眠時間は個人の自由である','睡眠の重要性を認識し、意識的に確保すべきだ','現代社会では睡眠不足は避けられない','睡眠時間より仕事を優先すべきだ'], a:1, type:'mainidea', d:'最終段落で「睡眠の重要性を再認識し、意識的に睡眠時間を確保する努力が必要」と結論づけています。'},
     {q:'本文によれば、睡眠時間が5時間未満の場合、どのような健康リスクがあるか。', opts:['風邪のリスクが高まる','糖尿病のリスクが約2.5倍、心筋梗塞のリスクが約2倍になる','記憶力が向上する','ストレスが軽減される'], a:1, type:'detail', d:'本文で「睡眠時間が5時間未満の場合、糖尿病のリスクは約2.5倍に、心筋梗塞のリスクは約2倍に増加する」と述べられています。'},
   ]},
  {id:'r10', lv:'N2', kind:'情報検索', title:'カルチャーセンター春期講座のご案内', src:'rbnhd/jlpt-n2-reading #004',
   paras:['【市民カルチャーセンター　春期講座募集】',
          '当センターでは、春期講座（4月～6月、全12回）の受講生を募集いたします。初めての方も経験者の方も大歓迎です。',
          '■料理教室<br>・初級コース：毎週火曜 10:00-12:00（和食中心）<br>・中級コース：毎週木曜 14:00-16:00（洋食・中華）<br>・受講料：各12,000円（材料費込み）<br>・定員：各15名<br>※エプロン、三角巾をご持参ください<br>※アレルギーのある方は事前にお知らせください',
          '■語学講座<br>・英会話（初級）：毎週月曜 19:00-20:30（日常会話）<br>・中国語（入門）：毎週水曜 19:00-20:30（発音から）<br>・韓国語（初級）：毎週金曜 19:00-20:30（ハングルから）<br>・受講料：各15,000円（テキスト代別途3,000円）<br>・定員：各20名<br>※ネイティブ講師が担当します',
          '■フィットネス<br>・ヨガ：毎週土曜 9:00-10:00（リラックスヨガ）<br>・ピラティス：毎週日曜 10:00-11:00（体幹トレーニング）<br>・受講料：各10,000円<br>・定員：各25名<br>※ヨガマット貸出無料<br>※動きやすい服装でお越しください',
          '【申込方法】<br>2月1日（木）9:00より受付開始<br>・窓口申込：センター1階受付にて（その場で手続き完了）<br>・電話申込：03-1234-5678（平日9:00-17:00）<br>・Web申込：当センターホームページより（24時間受付）',
          '※定員になり次第締め切ります<br>※受講料は初回授業時に現金またはクレジットカードでお支払いください<br>※一度納入された受講料は原則として返金できません'],
   qs:[
     {q:'料理教室の中級コースを受講したい人が用意すべきものは何か。', opts:['動きやすい服装','エプロンと材料費','テキストと15,000円','エプロンと三角巾'], a:3, type:'retrieval', d:'料理教室は受講料12,000円（材料費込み）で、エプロンと三角巾を持参する必要があります。'},
     {q:'平日の夜に通える講座の中で、最も費用が高いのはどれか。', opts:['英会話（初級）','韓国語（初級）','どれも同じ費用','中国語（入門）'], a:2, type:'retrieval', d:'語学講座はすべて15,000円+テキスト代3,000円で計18,000円となり、同じ費用です。'},
     {q:'Web申込の特徴は何か。', opts:['優先的に受付される','手数料が無料','24時間受付可能','割引がある'], a:2, type:'retrieval', d:'Web申込は「24時間受付」と明記されています。'},
   ]},
  {id:'r11', lv:'N2', kind:'情報検索', title:'お祭りボランティア募集', src:'rbnhd/jlpt-n2-reading #010',
   paras:['【第25回さくら祭り　ボランティアスタッフ大募集！】',
          '開催日：4月7日（土）・8日（日）午前9:00～午後5:00<br>場所：中央公園特設会場（JR中央駅より徒歩5分）',
          '例年5万人以上が訪れる地域最大級の春のイベントです。今年は25回目の記念大会となり、より多くのボランティアの皆様のご協力が必要です。皆さんと一緒に、素晴らしいお祭りを作り上げていきたいと思います！',
          '■募集内容<br>①会場案内係（各日20名）<br>・来場者への案内、パンフレット配布、迷子対応<br>・経験不問、笑顔で元気に対応できる方<br>・外国語対応可能な方は特に歓迎（英語、中国語など）',
          '②屋台運営補助（各日15名）<br>・地元名物料理、飲み物の販売補助、レジ対応<br>・立ち仕事が可能で、接客が好きな方<br>・食品衛生講習会に参加していただきます（4月1日開催予定）',
          '③環境美化係（各日10名）<br>・会場内のゴミ回収、分別指導、トイレ清掃<br>・体力に自信のある方、環境問題に関心のある方歓迎',
          '④子供広場係（各日8名）<br>・子供向けゲームコーナーの運営補助、安全管理<br>・子供が好きな方、保育・教育経験者優遇<br>・応急手当の基礎知識があれば尚可',
          '■参加特典<br>・昼食支給（特製弁当・飲み物）<br>・記念Tシャツプレゼント（サイズ指定可）<br>・交通費補助（上限1,000円/日）<br>・ボランティア活動証明書発行（希望者のみ、就職活動等に活用可）<br>・打ち上げ交流会ご招待（4月15日予定）',
          '■応募条件<br>・18歳以上（高校生不可）<br>・両日参加できる方を優先的に採用<br>・事前説明会（3月25日土曜日14:00～16:00、市民会館にて）への参加必須<br>・当日は動きやすい服装でご参加ください',
          '■応募方法<br>下記のいずれかの方法でご連絡ください。<br>メール：sakura@festival.jp（件名に「ボランティア応募」と明記）<br>電話：0120-XXX-XXXX（受付：平日10:00～16:00）<br>Webフォーム：www.sakurafes.jp/volunteer',
          '締切：3月20日（火）必着<br>※応募者多数の場合は、抽選となります。結果は3月22日までにメールでお知らせします。'],
   qs:[
     {q:'子供広場係として応募したい大学生が確認すべき条件は何か。', opts:['3月25日の説明会に参加できるかどうか','保育経験があるかどうか','記念Tシャツのサイズ','昼食の内容'], a:0, type:'retrieval', d:'応募条件として「事前説明会（3月25日14:00～）に参加可能な方」とあり、これは必須条件です。保育経験は優遇条件であり必須ではありません。'},
     {q:'高校3年生で18歳の人は応募できるか。', opts:['保護者の同意があればできる','記載されていない','できない','できる'], a:2, type:'retrieval', d:'応募条件に「18歳以上（高校生不可）」と明記されているため、18歳でも高校生は応募できません。'},
   ]},
  {id:'r12', lv:'N2', kind:'内容理解・短文', title:'新入社員研修のお知らせ', src:'rbnhd/jlpt-n2-reading #001',
   paras:['社員各位',
          '4月15日（月）午前9時より、新入社員向けの研修を開催します。今回の研修では、会社の基本方針や業務システムの使い方について説明します。また、ビジネスマナーや社内ルールに関する講習も実施いたします。',
          '参加対象者は今年度入社の新入社員全員となっており、必須参加です。当日は筆記用具とノートパソコンをご持参ください。昼食は会社が用意いたします。なお、研修は午後5時までの予定ですが、質疑応答の時間によっては若干延長する可能性があります。',
          'やむを得ない理由で欠席される場合は、前日までに人事部の田中までご連絡ください。後日、個別に研修内容をお伝えします。また、当日配布する資料は社外秘情報を含むため、研修終了後は必ず人事部に返却していただきますようお願いいたします。'],
   qs:[
     {q:'この文章によると、新入社員がすぐに準備しなければならないものは何か。', opts:['研修の申込書','昼食と飲み物','会社の資料','筆記用具とノートパソコン'], a:3, type:'detail', d:'文章中に「当日は筆記用具とノートパソコンをご持参ください」と明記されています。昼食は会社が用意すると書かれています。'},
     {q:'欠席する場合の対応について正しいものはどれか。', opts:['前日までに人事部に連絡する','研修後に報告書を提出する','特に連絡は必要ない','当日の朝に連絡する'], a:0, type:'detail', d:'「前日までに人事部の田中までご連絡ください」と明確に記載されています。'},
     {q:'研修資料について正しいものはどれか。', opts:['研修後に返却する必要がある','自宅に持ち帰ってもよい','コピーして配布してもよい','特に指示はない'], a:0, type:'detail', d:'「当日配布する資料は社外秘情報を含むため、研修終了後は必ず人事部に返却していただきます」と記載されています。'},
   ]},
  {id:'r13', lv:'N2', kind:'内容理解・中文', title:'日本の読書離れについて', src:'rbnhd/jlpt-n2-reading #002',
   paras:['最近の調査によると、日本人の読書時間が年々減少している傾向にある。特に20代から30代の若い世代では、1か月に1冊も本を読まない人が半数を超えているという衝撃的な結果が出ている。この数字は、10年前と比べて約20%も増加しており、読書離れが深刻な問題となっていることが分かる。',
          'この現象の背景には、スマートフォンの急速な普及が大きく関わっている。通勤時間や休憩時間に、以前は本を読んでいた人も、今ではSNSや動画を見ることが圧倒的に多くなった。情報を得る手段が多様化したことで、必ずしも本を読む必要がなくなったとも言える。短時間で手軽に楽しめるコンテンツが溢れているため、時間をかけて本を読むことが敬遠されがちだ。',
          'しかし、読書には動画やSNSでは決して得られない独自の価値がある。本を読むことで、想像力が養われ、論理的思考力も自然と身につく。また、長い文章を読み通す集中力や忍耐力は、仕事や勉強においても必ず役立つはずだ。さらに、読書は語彙力を高め、表現力を豊かにする効果も期待できる。',
          '読書離れを防ぐためには、子供の頃から本に親しむ環境を作ることが何より重要だ。学校や家庭で読書の楽しさを積極的に伝え、本を読む習慣を身につけさせる必要がある。デジタル時代だからこそ、読書の持つ本質的な価値を改めて見直すべきではないだろうか。'],
   qs:[
     {q:'筆者が読書離れの主な原因として挙げているものは何か。', opts:['本の値段が高くなったこと','仕事が忙しくなったこと','スマートフォンの普及','図書館が減少したこと'], a:2, type:'alasan', d:'第2段落で「この現象の背景には、スマートフォンの急速な普及が大きく関わっている」と明確に述べられています。'},
     {q:'筆者が読書の価値として述べていないものはどれか。', opts:['想像力が養われる','論理的思考力が身につく','外国語が上達する','集中力が身につく'], a:2, type:'detail', d:'第3段落で想像力、論理的思考力、集中力、語彙力、表現力について言及していますが、外国語の上達については触れていません。'},
     {q:'筆者の主張として最も適切なものはどれか。', opts:['学校での読書教育を廃止すべきだ','デジタル機器の使用を制限すべきだ','電子書籍を普及させるべきだ','読書の価値を再認識し、読書習慣を育てるべきだ'], a:3, type:'mainidea', d:'最終段落で「デジタル時代だからこそ、読書の持つ本質的な価値を改めて見直すべき」と結論づけ、読書習慣の重要性を強調しています。'},
   ]},
  {id:'r14', lv:'N2', kind:'内容理解・短文', title:'環境に優しい買い物', src:'rbnhd/jlpt-n2-reading #003',
   paras:['最近、エコバッグを持参する人が全国的に増えています。2020年7月にプラスチック製のレジ袋が有料化されたことで、多くの人が環境問題を意識するようになりました。スーパーやコンビニでも、エコバッグの利用を推奨する張り紙が見られるようになっています。',
          'ただし、エコバッグも使い方によっては環境に負担をかけることがあります。例えば、エコバッグを何個も買って使わないままにしていたり、すぐに新しいものに買い替えたりすることは、かえって資源の無駄遣いになります。一つのエコバッグを作るのにも、多くの資源とエネルギーが必要だからです。',
          '大切なのは、一つのエコバッグを長く大切に使い続けることです。汚れたら洗って清潔に保ち、破れたら修理するなど、物を大切にする姿勢が求められます。そうすることで、本当の意味で環境に優しい買い物ができるのです。'],
   qs:[
     {q:'エコバッグを使う人が増えた理由は何か。', opts:['エコバッグが安くなったから','エコバッグのデザインが良くなったから','レジ袋が有料化されたから','お店がエコバッグを配布したから'], a:2, type:'alasan', d:'文章に「プラスチック製のレジ袋が有料化されたことで」と明記されています。'},
     {q:'筆者が最も伝えたいことは何か。', opts:['エコバッグをたくさん持つべきだ','エコバッグを長く大切に使うべきだ','エコバッグは使わない方がよい','新しいエコバッグを買うべきだ'], a:1, type:'mainidea', d:'最終段落で「大切なのは、一つのエコバッグを長く大切に使い続けること」と結論づけています。'},
   ]},
  {id:'r15', lv:'N2', kind:'内容理解・中文', title:'駅前の古い喫茶店', src:'rbnhd/jlpt-n2-reading #006',
   paras:['駅前に40年以上続く喫茶店「カフェ・モーニング」がある。店主の山田さんは、もう70歳を過ぎているが、毎朝5時に起きてコーヒー豆を手作業で挽いている。昔から変わらないやり方を守り続けているのだ。',
          '「機械で挽いた方がずっと楽だし、時間も節約できるけど、手で挽いた方が香りが全然違うんですよ」と山田さんは誇らしげに言う。確かに、店に入った瞬間から漂うコーヒーの香りは格別だ。木製のテーブルと椅子、少し色褪せた壁の写真、昭和の雰囲気が残る店内は、時が止まったかのようである。',
          '常連客の多くは、山田さんと同じくらいの年齢の人たちだ。彼らは毎朝決まった時間に来て、同じ席に座り、同じメニューを注文する。新聞を読みながらゆっくりとコーヒーを飲む姿は、この店ならではの光景だ。「ここに来ると心が落ち着くんです。新しいおしゃれなカフェもいいけど、やっぱりここが一番居心地がいい」と常連の一人が話してくれた。',
          'しかし、最近は若い客も増えてきた。SNSで「昭和レトロな隠れ家喫茶店」として話題になったからだ。山田さんは少し戸惑いながらも、「若い人たちが来てくれるのは嬉しい。昔ながらの喫茶店の良さを知ってもらえるいい機会だ」と笑顔を見せた。',
          '時代は変わっても、この喫茶店は変わらない。その一貫性が、世代を超えて多くの人を惹きつける理由なのかもしれない。'],
   qs:[
     {q:'山田さんが手でコーヒー豆を挽く理由は何か。', opts:['機械を持っていないから','手で挽いた方が香りが良いから','客に頼まれたから','時間に余裕があるから'], a:1, type:'alasan', d:'山田さんは「手で挽いた方が香りが全然違うんですよ」と述べています。'},
     {q:'若い客が増えた理由は何か。', opts:['値段を下げたから','SNSで話題になったから','メニューを変更したから','駅前に大学ができたから'], a:1, type:'alasan', d:'文章に「SNSで『昭和レトロな隠れ家喫茶店』として話題になったから」と明記されています。'},
     {q:'この喫茶店の魅力は何か。', opts:['最新の設備があること','価格が安いこと','メニューが豊富なこと','昔から変わらないこと'], a:3, type:'detail', d:'最後の段落で「時代は変わっても、この喫茶店は変わらない」ことが魅力だと述べられています。'},
   ]},
  {id:'r16', lv:'N2', kind:'内容理解・中文', title:'AIと仕事の未来', src:'rbnhd/jlpt-n2-reading #009',
   paras:['人工知能（AI）の急速な発展により、私たちの仕事は根本的に変わろうとしている。一部では「AIに仕事を奪われる」という不安の声も聞かれるが、実際のところはどうなのだろうか。歴史を振り返れば、産業革命の時も同様の不安があったが、結果的には新しい仕事が生まれた。',
          '確かに、単純作業や定型的な業務はAIに置き換えられる可能性が高い。データ入力や簡単な分析作業、書類のチェックなどは、すでにAIが人間より遥かに速く正確に行えるようになっている。会計処理や在庫管理なども自動化が進んでいる。しかし、これは必ずしも悪いことではない。むしろ、チャンスと捉えるべきだ。',
          '人間がAIに単純作業を任せることで、より創造的で価値の高い仕事に集中できるようになる。企画立案、問題解決、人間関係の構築、感情に寄り添った対応など、AIには難しい領域で人間の能力を最大限に発揮できるのだ。人間にしかできない、想像力や共感力を必要とする仕事の重要性が高まっている。',
          'また、AIの登場により新しい職業も続々と生まれている。AIエンジニア、データサイエンティスト、AIトレーナー、倫理コンサルタントなど、10年前には存在しなかった職業が今では社会に不可欠な役割を果たしている。これらの職業は高い専門性が求められ、将来性も期待できる。',
          '重要なのは、AIを恐れるのではなく、AIと共存する方法を積極的に学ぶことだ。AIの特性を理解し、それを効果的に活用するスキルを身につけることが、これからの時代に最も求められる能力である。AIは人間の敵ではなく、強力なパートナーになり得る存在なのだ。'],
   qs:[
     {q:'AIに置き換えられる可能性が高い仕事の特徴は何か。', opts:['問題解決が必要な仕事','創造性が求められる仕事','人間関係の構築が必要な仕事','単純作業や定型的な業務'], a:3, type:'detail', d:'第2段落で「単純作業や定型的な業務はAIに置き換えられる可能性が高い」と明記されています。'},
     {q:'AIの登場によってもたらされた良い変化として述べられていないものはどれか。', opts:['人間が創造的な仕事に集中できる','新しい職業が生まれた','作業の速度と正確性が向上した','すべての仕事がなくなる'], a:3, type:'negasi', d:'すべての仕事がなくなるという記述はなく、むしろ新しい職業が生まれることが述べられています。'},
     {q:'筆者が最も伝えたいことは何か。', opts:['AIと共存する方法を学ぶことが重要だ','AIは危険なので使用を控えるべきだ','AIはすぐに人間を超える','AIの開発を止めるべきだ'], a:0, type:'mainidea', d:'最終段落で「AIを恐れるのではなく、AIと共存する方法を積極的に学ぶことだ」と主張しています。'},
   ]},
  {id:'r17', lv:'N2', kind:'主張理解・長文', title:'伝統工芸の継承', src:'rbnhd/jlpt-n2-reading #012',
   paras:['京都の古い町並みの片隅に、三代にわたって続く漆器工房「田中漆器店」がある。現在の主人である田中さんは、祖父の代から数えてこの道40年のベテラン職人だ。しかし、最近は注文が激減し、工房の経営は厳しくなる一方だった。かつては年に数百個の注文があったが、今では年に数十個程度にまで落ち込んでいる。',
          '「漆器は日本が世界に誇るべき伝統工芸なのに、若い世代の人たちはまったく興味を持ってくれない」田中さんは深いため息をつく。確かに、漆器は一つ作るのに何週間もかかり、その分高価になる。また、手入れも面倒で、電子レンジや食洗機も使えない。便利さを追求する現代の生活スタイルには、どうしても合わないのかもしれない。田中さんは自分の代で工房を閉めることも考え始めていた。',
          'ある春の日、田中さんの工房に一人の若者が訪ねてきた。美術大学を卒業したばかりの山本という青年だった。「僕に漆器の技術を教えてください。お願いします」山本の真剣な眼差しと熱い言葉に、田中さんは驚きを隠せなかった。最近では、弟子入りを希望する若者などほとんどいなかったからだ。',
          '山本は言った。「確かに伝統的な形の漆器は現代の生活に合わないかもしれません。でも、何百年も受け継がれてきた伝統技術を活かして、新しいものを作ることはできるはずです」そして、スマートフォンケースや腕時計のベルト、アクセサリーなど、現代的な製品に漆塗りを施すアイデアを次々と提案した。外国人観光客向けに英語の説明書を付けたり、オンラインショップで販売したりする計画も話してくれた。',
          '最初は渋っていた田中さんも、山本の情熱と具体的なアイデアに徐々に心を動かされ、新しい挑戦を始めることを決意した。伝統技術はそのままに、形を変えて現代に適応させる。それは邪道かもしれないが、技術を絶やさないためには必要なステップだと田中さんは考えるようになった。守るだけでなく、時代に合わせて進化させることも、伝統を次の世代に繋ぐ責任なのだと。',
          '半年後、二人が協力して作った漆塗りのスマートフォンケースがSNSで話題になった。日本の伝統美と現代のデザインが融合した製品は、国内外から高い評価を受け、注文が殺到した。工房は久しぶりに活気を取り戻し、若い職人志望者も数名訪れるようになった。伝統は、ただ守るだけでなく、時代に合わせて柔軟に進化させることも大切なのだ。田中さんは、山本という優秀な若い弟子を得て、新たな希望と可能性を見出していた。伝統工芸の未来は、決して暗くないのかもしれない。'],
   qs:[
     {q:'田中さんが最初に抱えていた問題は何か。', opts:['材料が手に入らないこと','注文が減り経営が厳しいこと','技術を教える時間がないこと','工房が狭いこと'], a:1, type:'detail', d:'第1段落で「注文が激減し、工房の経営は厳しくなる一方だった」と述べられています。'},
     {q:'山本が提案した解決策は何か。', opts:['漆器の値段を下げる','海外に販売する','伝統技術を現代製品に応用する','政府の補助金を申請する'], a:2, type:'detail', d:'山本は「スマートフォンケースや腕時計のベルト、アクセサリーなど、現代的な製品に漆塗りを施す」ことを提案しました。'},
     {q:'この話から学べる教訓は何か。', opts:['伝統は時代に合わせて進化させることも大切','伝統は変えてはいけない','若者の意見は聞くべきではない','SNSは使わない方がよい'], a:0, type:'detail', d:'最終段落で「伝統は、ただ守るだけでなく、時代に合わせて柔軟に進化させることも大切なのだ」と結論づけています。'},
   ]},
  {id:'r18', lv:'N2', kind:'内容理解・短文', title:'食品ロスを減らすために', src:'rbnhd/jlpt-n2-reading #013',
   paras:['日本では年間約600万トンもの食品が廃棄されている。これは、国民一人当たり毎日お茶碗一杯分のご飯を捨てていることになる。農林水産省の調査によると、この量は世界中で飢餓に苦しむ人々への食糧援助量の約2倍に相当するという。',
          '食品ロスの主な原因は、買いすぎ、賞味期限切れ、飲食店での食べ残しなどだ。特に家庭での廃棄量が全体の約半分を占めており、一人ひとりの意識改革が重要となっている。コンビニやスーパーでの売れ残りも大きな課題で、多くの店舗が閉店前の値引き販売などで対策を進めている。',
          '食品ロスを減らすには、買い物前に冷蔵庫の中身をチェックする、必要な分だけ調理する、残った食材は冷凍保存するなど、日々の小さな心がけが大切だ。また、賞味期限と消費期限の違いを正しく理解することも重要である。賞味期限は「美味しく食べられる期限」であり、過ぎてもすぐに食べられなくなるわけではない。一人ひとりが意識を変えることで、環境にも家計にも優しい生活が実現できるのである。'],
   qs:[
     {q:'日本の年間食品廃棄量は何トンか。', opts:['約1200万トン','約300万トン','約900万トン','約600万トン'], a:3, type:'detail', d:'本文の冒頭で「日本では年間約600万トンもの食品が廃棄されている」と明記されています。'},
     {q:'食品ロスを減らすための対策として本文で述べられていないものはどれか。', opts:['買い物前に冷蔵庫をチェックする','必要な分だけ調理する','食材をすべて有機野菜に変える','残った食材を冷凍保存する'], a:2, type:'negasi', d:'有機野菜に変えることについては本文では触れられていません。a、b、dは第3段落で具体的な対策として挙げられています。'},
   ]},
  {id:'r19', lv:'N2', kind:'内容理解・中文', title:'現代人とストレス', src:'rbnhd/jlpt-n2-reading #015',
   paras:['佐藤さんは都内の大手IT企業に勤める35歳の会社員だ。毎朝7時に家を出て、満員電車に1時間揺られて通勤し、オフィスに着くと朝9時から夜11時まで休みなくパソコンの前に座り続ける。帰宅すると日付が変わっていることも珍しくない。そんな生活が2年以上続いていた。',
          '「最近、夜ベッドに入っても全然眠れないんです。頭の中で仕事のことばかり考えてしまって…」佐藤さんは会社の健康診断で医者に相談した。詳しく話を聞いた医者は、ストレスによる不眠症と診断した。「現代社会では、佐藤さんのような症状を訴える人が年々増えています。仕事のプレッシャー、人間関係の悩み、将来への不安。これらが複雑に絡み合って、心身に深刻な影響を与えているのです。このまま放置すると、うつ病などより深刻な状態になる可能性もあります」医者の言葉に、佐藤さんははっとした。',
          '医者は具体的なアドバイスをくれた。まず、できる限り残業を減らして最低7時間の睡眠時間を確保すること。週に2回は軽い運動をすること。そして何より、仕事以外の趣味を持つこと。佐藤さんは上司に相談し、業務の見直しを行った。また、学生時代に夢中になっていた写真撮影を再開することにした。週末は近所の公園や神社を散歩しながら、四季折々の風景をカメラに収めるようになった。夜寝る1時間前にはスマートフォンを見ないようにし、代わりに軽いストレッチや好きな音楽を聴く時間を作った。',
          '最初の1か月は変化を感じられなかったが、3か月後、佐藤さんの表情は明るくなっていた。「完全にストレスがなくなったわけではありませんが、以前よりずっと上手く付き合えるようになりました。夜もぐっすり眠れますし、朝は目覚まし時計が鳴る前に自然と目が覚めます。写真という新しい楽しみもできて、人生が豊かになった気がします」と佐藤さんは笑顔で話す。',
          'ストレスは現代社会で避けられないものだが、適切な対処法を知っていれば、健康的でバランスの取れた生活を送ることができる。大切なのは、自分に合った方法を見つけ、早めに実践することなのだ。'],
   qs:[
     {q:'佐藤さんが医者に相談した理由は何か。', opts:['頭が痛いから','食欲がないから','よく眠れないから','仕事を辞めたいから'], a:2, type:'alasan', d:'第2段落で「最近、よく眠れないんです」と医者に相談したことが述べられています。'},
     {q:'佐藤さんが実践した対策として述べられていないものはどれか。', opts:['残業を減らした','転職した','寝る前のスマートフォンをやめた','運動する時間を作った'], a:1, type:'negasi', d:'転職については言及されていません。残業を減らしたとは書かれていますが、転職したとは書かれていません。'},
     {q:'この文章の主要なメッセージは何か。', opts:['ストレスとの付き合い方を学ぶことが大切だ','ストレスは完全になくすべきだ','医者に相談する必要はない','仕事を辞めるべきだ'], a:0, type:'mainidea', d:'最終段落で「ストレスは避けられないものだが、対処法を知っていれば、健康的な生活を送ることができる」と結論づけています。'},
   ]},
  {id:'r20', lv:'N2', kind:'内容理解・短文', title:'テレワーク導入に関するお知らせ', src:'rbnhd/jlpt-n2-reading #016',
   paras:['社員各位',
          '働き方改革の一環として、来月1日よりテレワーク制度を本格的に導入することになりました。この制度により、週2日まで在宅勤務が可能となります。',
          '対象となるのは、入社3年目以上の正社員です。希望者は所属部署の上司に申請書を提出し、承認を得る必要があります。なお、業務の性質上、現場での作業が必要な部署については対象外となる場合があります。',
          'テレワーク実施日は、業務に支障がないよう、チームメンバーと調整してください。また、セキュリティ対策として、会社から貸与されたパソコンを使用し、公共のWi-Fiの利用は避けてください。',
          '詳細については、人事部のホームページをご確認いただくか、内線2345までお問い合わせください。'],
   qs:[
     {q:'テレワーク制度について正しいものはどれか。', opts:['週2日まで在宅勤務ができる','個人のパソコンを使用する','自動的に適用される','全社員が対象である'], a:0, type:'detail', d:'文章中に「週2日まで在宅勤務が可能」と明記されています。対象は入社3年目以上で、申請が必要です。'},
     {q:'テレワーク実施にあたって注意すべきことは何か。', opts:['できるだけカフェで仕事をする','毎日在宅勤務をする','上司の許可は不要である','チームメンバーと調整し、会社のパソコンを使用する'], a:3, type:'detail', d:'「チームメンバーと調整」し、「会社から貸与されたパソコンを使用」することが求められています。'},
   ]},
  {id:'r21', lv:'N2', kind:'内容理解・中文', title:'取引先との商談マナー', src:'rbnhd/jlpt-n2-reading #017',
   paras:['ビジネスにおいて、取引先との商談は企業の未来を左右する重要な機会である。しかし、新入社員の中には、適切なマナーを知らないまま商談に臨む人も少なくない。基本的な商談マナーを身につけることは、ビジネスパーソンとしての第一歩だ。ここでは、押さえておくべき基本的なポイントについて説明する。',
          'まず、時間厳守は絶対である。遅刻は相手への失礼となるだけでなく、会社全体の信用を損なう深刻な問題だ。やむを得ず遅れる場合は、できるだけ早く、遅くとも約束の30分前までには連絡を入れることが重要である。また、約束の時間の5分前には到着し、受付で待機するのが望ましい。早すぎる到着も相手に準備の負担をかけるため、適切な時間配分を心がけよう。',
          '商談の場では、名刺交換が最初の重要なステップとなる。名刺は両手で丁寧に渡し、相手の名刺も両手で受け取る。受け取った名刺は、すぐにポケットやカバンにしまわず、テーブルの上に丁寧に置いておくのがマナーだ。これにより、相手の名前や役職を何度も確認でき、会話の際にも役立つ。商談が終わるまで、名刺はテーブルに出しておくことが礼儀とされている。',
          '話し方にも十分な注意が必要である。専門用語や業界用語を使いすぎると、相手が理解できない可能性がある。常にわかりやすい言葉で、要点を簡潔に説明することが大切だ。また、自社の製品やサービスについて一方的に話すのではなく、相手のニーズや課題を聞き出す姿勢を示すことも重要である。良い商談は、双方向のコミュニケーションから生まれる。',
          '最後に、商談後のフォローアップを忘れてはいけない。商談が終わったその日のうちに、内容を確認するメールを送り、次のステップについて明確にする。この一手間が、相手に誠実な印象を与え、良好なビジネス関係を築く鍵となるのだ。'],
   qs:[
     {q:'商談で遅刻する場合、どうすべきか。', opts:['特に連絡は必要ない','できるだけ早く連絡する','商談が終わってから謝罪する','商談をキャンセルする'], a:1, type:'detail', d:'「やむを得ず遅れる場合は、できるだけ早く連絡を入れることが重要」と述べられています。'},
     {q:'名刺交換について正しいものはどれか。', opts:['受け取ったらすぐにしまう','受け取った名刺はテーブルに置いておく','片手で渡してもよい','名刺交換は必須ではない'], a:1, type:'detail', d:'「受け取った名刺は、すぐにしまわず、テーブルの上に置いておくのがマナー」と説明されています。'},
     {q:'良好なビジネス関係を築くために重要なこととして述べられているのは何か。', opts:['商談後のフォローアップ','専門用語を多用すること','一方的に話すこと','高価な贈り物を渡すこと'], a:0, type:'detail', d:'最後の段落で「商談後のフォローアップ」が「良好なビジネス関係を築く鍵」と述べられています。'},
   ]},
  {id:'r22', lv:'N2', kind:'主張理解・長文', title:'プロジェクト進捗報告書の作成', src:'rbnhd/jlpt-n2-reading #018',
   paras:['ビジネスの現場において、プロジェクトの進捗報告書は非常に重要な文書である。単なる作業の記録や形式的な提出物ではなく、プロジェクトの現状を正確に把握し、問題点を早期に発見し、チーム全体で情報を共有するための重要なコミュニケーションツールとなる。効果的な報告書を作成するには、いくつかの重要なポイントを押さえる必要がある。',
          'まず第一に、報告書の構成を明確にすることが重要だ。一般的には、①プロジェクトの概要と目標、②当期の主な成果と達成率、③現在直面している課題と対策、④次期の具体的な計画とマイルストーン、という流れで記載する。この論理的な構成により、読み手は全体像を素早く理解できる。特に、経営層や他部署のメンバーなど、プロジェクトの詳細を日常的に把握していない人が読む場合、このようなわかりやすい構成は不可欠である。忙しい読み手が短時間で要点を掴めるよう、最初に要約を付けることも効果的だ。',
          '次に、客観的な数値を積極的に活用することである。「順調に進んでいる」「ほぼ完了している」といった主観的で曖昧な表現ではなく、「予定の85%が完了」「目標に対して92%達成」のように具体的な数値やパーセンテージで示すことで、客観性と信頼性が大幅に増す。また、ガントチャートや進捗グラフ、円グラフなどの視覚的な図表を用いることで、一目で状況を理解しやすくなる。ただし、単にデータを羅列するだけでは意味がない。数値の背景にある要因、たとえば「人員不足により遅延が発生」「新技術の導入により効率が30%向上」など、それが何を意味するのかを丁寧に説明することが重要だ。',
          'さらに、課題については正直かつ具体的に報告することが強く求められる。問題を隠したり、実際より小さく見せたりすると、適切な対策が取れず、後で取り返しのつかない大きなトラブルに発展する可能性がある。課題を明確に記載した上で、「誰が、いつまでに、どのような方法で解決するのか」という具体的な対策を必ず提示することで、読み手の信頼を得られる。ここで重要なのは、単に問題点を指摘して終わるのではなく、実行可能な解決策も併せて示すことである。無責任な問題提起は、かえって不安を増大させる。',
          '最後に、報告書の文章は簡潔で読みやすくあるべきだ。長くて複雑な文章は読み手の負担となり、重要なポイントが埋もれてしまう。箇条書きを効果的に活用し、一つの文を短くシンプルにまとめることで、読みやすさが大きく向上する。専門用語は必要最小限にとどめ、使用する場合は簡単な説明を加えると親切だ。',
          'こうした工夫と配慮により、プロジェクト進捗報告書は、単なる形式的な提出物ではなく、プロジェクト成功のための有効なコミュニケーションツールとなり、チーム全体の生産性向上に大きく貢献するのである。'],
   qs:[
     {q:'報告書の構成を明確にすることが重要な理由は何か。', opts:['報告書の分量を増やすため','専門用語を多く使用するため','読み手が全体像を素早く理解できるため','長い文章を書くため'], a:2, type:'alasan', d:'第2段落で「この構成により、読み手は全体像を素早く理解できる」と説明されています。'},
     {q:'数値を活用する際に重要なこととして述べられていることは何か。', opts:['数値の背景にある要因を説明する','曖昧な表現を使う','グラフや図表は使わない','できるだけ多くのデータを羅列する'], a:0, type:'detail', d:'第3段落で「数値の背景にある要因や、それが何を意味するのかを説明することが重要」と述べられています。'},
     {q:'筆者が考える効果的な報告書の特徴として正しくないものはどれか。', opts:['課題と対策を明示する','問題点を小さく見せる','具体的な数値を用いる','簡潔な文章で書く'], a:1, type:'negasi', d:'第4段落で「問題を隠したり、小さく見せたりすると、後で大きなトラブルに発展する」と述べ、正直な報告を推奨しています。'},
   ]},
  {id:'r23', lv:'N2', kind:'内容理解・短文', title:'地域の清掃活動参加者募集', src:'rbnhd/jlpt-n2-reading #019',
   paras:['市民の皆様へ',
          '来月12日（日曜日）午前9時から正午まで、市内全域の公園、道路、河川敷などで一斉清掃活動を実施いたします。この活動は、きれいで住みやすい街づくりを目指す市民運動の一環として、毎年春と秋の年2回、多くの市民の皆様にご協力いただき実施しているものです。昨年は約3000名の方々にご参加いただき、大変な成果を上げることができました。',
          '参加は自由で、事前の申し込みや登録は一切不要です。当日、お住まいの地域の指定集合場所に直接お集まりください。各地域の集合場所や担当エリアの詳細は、市の公式ホームページまたは市役所1階の掲示板でご確認いただけます。清掃用具（ゴミ袋、トング、手袋など）は市が用意しますので、手ぶらでお越しいただいて構いません。ただし、動きやすい服装、帽子、飲み物は各自でご用意ください。',
          '小雨の場合は決行いたしますが、大雨や台風などの荒天の場合は中止となります。中止の判断は当日午前7時に行い、市の公式ホームページおよび防災メールでお知らせいたします。きれいな街づくりのため、多くの市民の皆様のご参加を心よりお待ちしております。'],
   qs:[
     {q:'清掃活動に参加するために必要なことは何か。', opts:['事前に申し込みをする','参加費を支払う','清掃用具を持参する','集合場所を確認して当日集まる'], a:3, type:'detail', d:'「参加は自由で、事前の申し込みは不要」で「当日、お住まいの地域の集合場所にお集まりください」と書かれています。'},
     {q:'荒天の場合の対応について正しいものはどれか。', opts:['当日午前7時にホームページで中止を知らせる','屋内で実施する','翌週に延期する','決行する'], a:0, type:'detail', d:'「荒天の場合は中止となります。中止の判断は当日午前7時に行い、市の公式ホームページでお知らせいたします」と明記されています。'},
   ]},
  {id:'r24', lv:'N2', kind:'内容理解・中文', title:'プラスチックごみ削減の取り組み', src:'rbnhd/jlpt-n2-reading #020',
   paras:['世界中でプラスチックごみが深刻な環境問題となっている。特に海洋プラスチックは、生態系に大きな影響を与えており、早急な対策が求められている。',
          '日本でも、プラスチックごみ削減に向けた様々な取り組みが始まっている。2020年7月からは、全国の小売店でレジ袋が有料化された。これにより、多くの人がエコバッグを持参するようになり、レジ袋の使用量は大幅に減少した。当初は不便だという声もあったが、今では習慣として定着している。',
          'さらに、企業の取り組みも進んでいる。大手コーヒーチェーンでは、プラスチック製のストローを廃止し、紙製や生分解性のものに切り替えた。また、飲料メーカーでは、ペットボトルのリサイクル率を上げるため、回収ボックスを設置する動きが広がっている。',
          'しかし、課題も残る。リサイクルされるプラスチックごみは全体の約2割にとどまっており、残りは焼却されるか埋め立てられている。また、マイクロプラスチックと呼ばれる微細なプラスチック片が、食物連鎖を通じて人体に影響を及ぼす可能性も指摘されている。',
          'プラスチックごみ問題を解決するには、私たち一人一人の意識改革が不可欠だ。使い捨て製品をできるだけ避け、リユースやリサイクルを心がける必要がある。'],
   qs:[
     {q:'レジ袋有料化の効果として述べられていることは何か。', opts:['エコバッグの使用が増え、レジ袋の使用量が減った','レジ袋が完全になくなった','多くの人が不便を感じている','効果はなかった'], a:0, type:'detail', d:'第2段落で「多くの人がエコバッグを持参するようになり、レジ袋の使用量は大幅に減少した」と述べられています。'},
     {q:'現在のリサイクルの課題として正しいものはどれか。', opts:['リサイクルされるのは全体の約2割だけである','リサイクル率が100%に達している','リサイクルする技術がない','企業が協力していない'], a:0, type:'detail', d:'第4段落で「リサイクルされるプラスチックごみは全体の約2割にとどまっている」と指摘されています。'},
     {q:'筆者が最も伝えたいことは何か。', opts:['プラスチックを完全に禁止すべきだ','一人一人の意識改革が必要だ','企業だけが対策をすればよい','リサイクルは不要である'], a:1, type:'mainidea', d:'最終段落で「私たち一人一人の意識改革が不可欠」と結論づけています。'},
   ]},
  {id:'r25', lv:'N2', kind:'主張理解・長文', title:'高齢化社会と地域コミュニティ', src:'rbnhd/jlpt-n2-reading #021',
   paras:['日本は世界でも類を見ないスピードで高齢化が進んでいる。2025年には、65歳以上の高齢者が総人口の約30%を占めると予測されている。2050年にはこの割合が40%近くに達するとも言われており、この急速な人口構造の変化は、社会のあり方そのものを根本から変えつつある。',
          '高齢化がもたらす影響は実に多岐にわたる。まず、医療費や介護費の増大が国の財政を深刻に圧迫している。現在、社会保障費は国の予算の約3分の1を占めており、この割合は今後さらに拡大すると見込まれている。また、労働力人口の減少により、経済成長の鈍化も強く懸念されている。企業は人手不足に悩み、特に介護や建設などの現場では深刻な人材不足が続いている。さらに、地方では若者の都市部への流出と高齢化が同時に進行し、商店街はシャッターが閉まり、地域の活力が急速に失われつつある。このような状況は「地方消滅」とも呼ばれ、社会問題となっている。',
          'しかし、高齢化を単なる解決すべき社会問題として悲観的に捉えるのではなく、新たな可能性や社会変革のチャンスと前向きに考える動きもある。その鍵となるのが、地域コミュニティの再構築だ。従来の家族中心の介護から、地域全体で高齢者を支え、見守る仕組みへの転換が強く求められている。いわゆる「地域包括ケアシステム」の構築である。',
          '実際、全国各地で興味深く、示唆に富んだ取り組みが始まっている。ある地域では、高齢者と大学生が共に暮らすシェアハウスを開設し、世代間交流を積極的に促進している。高齢者は長年培った人生経験や知恵を若者に伝え、若者は買い物や掃除など日常生活のサポートを行う。家賃も通常より安く設定され、双方にとって経済的・精神的メリットがある関係が築かれている。入居者の間には温かい信頼関係が生まれ、孤独を感じていた高齢者も生き生きとした表情を取り戻しているという。',
          'また、別の地域では、高齢者の豊富な知識や長年培った技術を積極的に活かした地域活動が盛んだ。退職した元エンジニアが地域の小中学生にプログラミングやロボット工作を教えたり、料理が得意な高齢者が地域食堂を運営して子供たちに栄養バランスの取れた食事を提供したりしている。このような活動を通じて、高齢者が単なる「支えられる側」から「支える側」「教える側」になることで、社会とのつながりを実感し、大きな生きがいを感じられるのだ。',
          'こうした取り組みは、高齢者の孤立や孤独死を防ぐだけでなく、地域全体の活性化や世代を超えた絆の形成にもつながる。重要なのは、年齢や立場に関係なく、すべての住民が地域社会に主体的に参加し、それぞれの役割を持ち、お互いを認め合うことである。',
          '高齢化社会を乗り越えるには、制度や政策の充実、財政支援だけでは決して十分ではない。地域住民一人一人が、世代や背景の違いを超えてお互いを尊重し、助け合い、支え合う意識を持つことが何より大切である。それこそが、年齢を重ねても誰もが尊厳を持って安心して暮らせる社会、すなわち真の意味での「共生社会」を実現する第一歩となるはずだ。'],
   qs:[
     {q:'高齢化がもたらす影響として述べられていないものはどれか。', opts:['医療費や介護費の増大','労働力人口の減少','地方の活力低下','犯罪率の上昇'], a:3, type:'negasi', d:'犯罪率の上昇については言及されていません。医療費増大、労働力減少、地方の活力低下は述べられています。'},
     {q:'筆者が紹介している地域の取り組みの特徴は何か。', opts:['高齢者を施設に隔離する','高齢者と若者の交流や、高齢者の知識を活かす','高齢者に仕事を強制する','高齢者を家族だけで介護する'], a:1, type:'detail', d:'第4・5段落で、世代間交流のシェアハウスや、高齢者の知識を活かした地域活動が紹介されています。'},
     {q:'筆者が最も強調していることは何か。', opts:['政府が全ての問題を解決すべきだ','地域住民が支え合う意識を持つことが重要だ','高齢者は働くべきではない','若者だけで高齢者を支えるべきだ'], a:1, type:'mainidea', d:'最終段落で「地域住民一人一人が、お互いを尊重し、支え合う意識を持つことが何より大切」と結論づけています。'},
   ]},
  {id:'r26', lv:'N2', kind:'内容理解・中文', title:'「便利」と「幸せ」の関係', src:'rbnhd/jlpt-n2-reading #022',
   paras:['現代社会は、テクノロジーの目覚ましい進歩により驚くほど便利になった。スマートフォンさえあれば、いつでもどこでも世界中の情報を瞬時に得られるし、買い物も食事の注文もワンクリックで完了する。電車の乗り換え案内、天気予報、翻訳、地図、すべてが手のひらの中にある。移動手段も飛躍的に発達し、新幹線や飛行機を使えば短時間で日本中、いや世界中どこへでも行けるようになった。私たちの祖父母の世代からすれば、まさに夢のような時代である。',
          'しかし、こうして便利になればなるほど、私たちは本当に幸せになっているのだろうか。ふとそんな疑問を感じることがある。確かに時間は節約できるようになったが、その分、やるべきこと、やりたいことが増えて、結局いつも忙しく追われている気がする。メールやSNSの返信に追われ、「既読無視」を気にし、いいねの数を気にし、ゆっくりと物事を考える時間も、ぼんやりする時間もなくなってしまった。便利になったはずなのに、心の余裕は減っているのではないだろうか。',
          '昔、祖母の家に遊びに行くと、縁側で手紙を書く姿をよく見かけた。万年筆を持ち、一字一字、丁寧に書く祖母の穏やかな横顔を今でも思い出す。「お元気ですか」と始まり、季節の話、日常の小さな出来事が書かれていた。今のように即座に連絡が取れなかった時代は、確かに不便だったかもしれない。でも、手紙を書く静かな時間、ポストに投函する時のわくわく、返事を心待ちにする時間には、独特の豊かさと温かさがあったように思う。待つことにも、意味があったのだ。',
          '便利さを否定するつもりはまったくない。テクノロジーの恩恵を受けて、生活が格段に楽になったことも紛れもない事実だ。ただ、便利さに無自覚に流されるのではなく、時には立ち止まって考えることも必要ではないだろうか。本当に大切なものは何か、自分にとっての幸せとは何か、どう生きたいのか。便利さと引き換えに、私たちは何かを失っていないだろうか。そんなことをたまには考えてみたいと思う。'],
   qs:[
     {q:'筆者が感じている矛盾は何か。', opts:['便利になったのに、かえって忙しくなった','技術が進歩しなくなった','手紙を書く人が増えた','移動が不便になった'], a:0, type:'detail', d:'第2段落で「時間は節約できるようになったが、その分、やることが増えて忙しくなった」と述べられています。'},
     {q:'筆者が祖母の手紙について述べたいことは何か。', opts:['もっと早く書くべきだった','不便で無駄だった','時間をかける豊かさがあった','メールの方が良い'], a:2, type:'detail', d:'第3段落で「手紙を書く時間、返事を待つ時間には、独特の豊かさがあった」と回想しています。'},
     {q:'筆者が最も言いたいことは何か。', opts:['技術を完全に否定すべきだ','便利さに流されず、大切なものを考えるべきだ','昔の生活に戻るべきだ','手紙だけを使うべきだ'], a:1, type:'mainidea', d:'最終段落で「便利さに流されるのではなく、時には立ち止まって考えることも必要」と主張しています。'},
   ]},
  {id:'r27', lv:'N2', kind:'主張理解・長文', title:'SNS時代のコミュニケーション', src:'rbnhd/jlpt-n2-reading #024',
   paras:['SNSの爆発的な普及により、私たちのコミュニケーションのあり方が根本から大きく変わった。わずか10年前には考えられなかったが、今や世界中の人と瞬時につながれる時代になり、写真や動画、意見や感情の共有も驚くほど容易になった。しかし、この劇的な変化は必ずしも良い面ばかりではなく、むしろ新たな問題を生み出している。',
          'SNSのメリットは確かに明らかだ。遠く離れた故郷の友人や海外に住む家族と簡単に連絡が取れ、写真や近況を共有できる。共通の趣味や関心を持つ世界中の人々とつながり、情報交換することもできる。また、東日本大震災のような大規模災害時には安否確認の迅速な手段としても大いに役立った。ビジネスの世界でも、SNSを活用したマーケティングやブランディングが主流となり、小さな企業でも世界に情報発信できるようになった。',
          'その一方で、SNSには見過ごせない深刻な問題も多数存在する。最も懸念されるのは、表面的で浅いつながりばかりが増え、真に深い人間関係が失われつつあることだ。数百人、数千人の「友達」や「フォロワー」がいても、本当に困った時に相談できる相手は何人いるだろうか。「いいね」の数を気にするあまり、自分を良く見せようとする投稿ばかりになり、本当の自分、弱い部分を表現できなくなる人も少なくない。また、他人の華やかな投稿と自分の日常を比較し、「みんなは幸せそうなのに、自分だけが不幸だ」と劣等感を抱く人が増えている。しかし、SNS上の投稿は、現実のほんの一部を切り取り、編集したものに過ぎないのだ。',
          'さらに深刻なのは、匿名性やアカウントの複数使用を利用した誹謗中傷の問題だ。相手の顔が見えないことで、普段の生活なら決して言わないような厳しく残酷な言葉を平気で投げかける人がいる。これにより、精神的に深く傷つき、最悪の場合は自殺に追い込まれる人が後を絶たない。特に多感な時期の若者への影響は極めて深刻で、SNS上でのいじめが大きな社会問題と化している。',
          '情報の信頼性と拡散速度も重大な課題だ。SNSでは、真偽が確認されていない情報、意図的に作られたフェイクニュースが瞬く間に何万人、何十万人に拡散される。人々はそれを十分に検証せず、感情的に反応し、さらにリツイートやシェアで広めてしまう。その結果、誤った判断や偏見、差別を助長することさえある。情報を安易に鵜呑みにせず、複数の情報源を確認し、批判的に考える力、いわゆるメディアリテラシーが今まで以上に求められている。',
          'では、私たちはSNSとどう向き合えばよいのか。SNSの存在自体を完全に否定したり、使用をやめたりするのは現実的ではない。重要なのは、SNSを賢く、主体的に利用することだと私は考える。SNSに支配され、振り回されるのではなく、自分がSNSという道具を使うのだという明確な意識を持つべきだ。具体的には、投稿を見る時間を1日30分までと決めたり、寝る前の1時間はスマートフォンを触らないルールを作ったり、週末には意図的にデジタルデトックス（SNSから離れる時間）を設けたりすることも有効だろう。',
          'そして何より、SNS上のつながりだけに依存せず、直接会って顔を見て話す機会を意識的に大切にすることだ。対面でのコミュニケーションでしか得られない温かさ、安心感、信頼感が確かに存在する。表情、声のトーン、間、沈黙、そういったものすべてが大切なメッセージなのだ。SNSは確かに便利で有用なツールだが、それが人間関係のすべてではない。オンラインとオフライン、バーチャルとリアル、そのバランスを保ちながら、健全で温かい人間関係を築いていくことが、現代を生きる私たちにとって最も重要なことである。'],
   qs:[
     {q:'SNSの問題として筆者が挙げていないものはどれか。', opts:['表面的なつながりが増えること','誹謗中傷が起きること','インターネットの速度が遅いこと','情報の信頼性が低いこと'], a:2, type:'detail', d:'インターネットの速度については言及されていません。他の3つは具体的な問題として挙げられています。'},
     {q:'筆者が考える情報への向き合い方として正しいものはどれか。', opts:['情報を批判的に考える','すべての情報を信じる','SNSの情報は見ない','情報は必要ない'], a:0, type:'detail', d:'第5段落で「情報を鵜呑みにせず、批判的に考える力が求められている」と述べられています。'},
     {q:'筆者が最も伝えたいことは何か。', opts:['SNSだけに頼るのではなく、バランスを保つことが大切だ','SNSを使う時間を増やすべきだ','対面コミュニケーションは不要だ','SNSは完全に悪いものだ'], a:0, type:'mainidea', d:'最後の段落で「バランスを保ちながら、健全な人間関係を築いていくことが重要」と結論づけています。'},
   ]},
  {id:'r28', lv:'N2', kind:'内容理解・中文', title:'雨の日の出会い', src:'rbnhd/jlpt-n2-reading #025',
   paras:['その日は朝から雨が降り続いていた。しかも、天気予報では午後まで止まないという。傘を家に忘れた私は、駅のホームの屋根の下で雨が止むのを待っていた。もう30分も経つのに、雨は弱まるどころか、むしろ強くなる気配さえある。会社には「少し遅れます」と連絡を入れたが、このままでは本当に遅刻してしまう。',
          '「困ったな...」と思わずつぶやいた時、隣に立っていた老人が優しい声で話しかけてきた。「お困りですか。よかったら、この傘をお使いください」',
          '驚いて顔を上げると、白髪で優しそうな笑顔の男性が、小さな折りたたみ傘を差し出していた。「でも、おじいさんは傘がなくなってしまいますよね...」と言いかけると、彼は穏やかに笑って答えた。「私はこれから地下鉄に乗るので大丈夫です。それに、もう一本カバンの中に持っていますから。こんな土砂降りの中、濡れて帰るのは大変でしょう。風邪をひいてしまいますよ」',
          '私は何度も何度もお礼を言って、ありがたく傘を借りた。その日の夜、家に帰ってから、傘をしまおうとした時、持ち手に小さなメモが丁寧に結びつけてあることに気づいた。開いてみると、こう書かれていた。「人に親切にすることは、いつか巡り巡って自分に返ってきます。今度は、あなたが誰かを助けてあげてください。親切の輪が広がりますように」文字は震える手で書かれたようだったが、温かい気持ちが伝わってきた。',
          'あれから5年が経つ。あの時にいただいた傘は今でも大切に使っている。そして、電車の中で困っている人を見かけたり、道に迷っている外国人観光客を見かけたりしたら、必ず声をかけるようにしている。最初は少し勇気がいったが、今では自然にできるようになった。あの老人の言葉通り、親切は連鎖し、社会を少しずつ温かくするものなのだと、私は心から信じている。見知らぬ人からもらった小さな親切が、私の人生観を変えてくれたのだ。'],
   qs:[
     {q:'老人が傘を貸した理由は何か。', opts:['傘が不要になったから','傘を売りたかったから','知り合いだったから','もう一本傘を持っていて、困っている人を助けたかったから'], a:3, type:'alasan', d:'老人は「私はもう一本持っていますから」と言い、親切心から傘を貸しています。'},
     {q:'メモに書かれていたことの意味は何か。', opts:['親切にしても無駄である','親切は連鎖するので、次は誰かを助けるべきだ','親切にされたら、返礼の品を送るべきだ','傘を返してほしい'], a:1, type:'detail', d:'メモには「次は誰かを助けてあげてください」とあり、親切の連鎖を促しています。'},
     {q:'この経験が「私」に与えた影響は何か。', opts:['雨の日が嫌いになった','困っている人を見かけたら助けるようになった','傘を複数持つようになった','老人を探すようになった'], a:1, type:'detail', d:'最後の段落で「困っている人を見かけたら、必ず声をかけるようにしている」と述べられています。'},
   ]},
  {id:'r29', lv:'N2', kind:'内容理解・中文', title:'母の味', src:'rbnhd/jlpt-n2-reading #026',
   paras:['一人暮らしを始めて早10年が経つ。当初は料理もまったくできなかったが、今ではそれなりにいろいろな料理を作れるようになった。しかし、どうしても母が作る料理の味には及ばない。特に、母が作る肉じゃがの味は、同じレシピで何度挑戦しても、どうしても再現できなかった。何かが違うのだ。',
          '先日、久しぶりに実家に帰省した時、思い切って母に作り方を直接教えてもらうことにした。「特別なことは何もないのよ。いつも適当に作ってるだけ」と言いながら、母はいつものエプロンをつけ、台所に立って手際よく野菜を切り始めた。じゃがいも、にんじん、玉ねぎ。分量も正確には測らず、調味料も「このくらいかな」と目分量で次々と入れていく。私は横で必死にメモを取ったが、ノートには「適量」「少々」「お好みで」という曖昧な言葉ばかりが並ぶだけだった。これでは自分で再現できないではないか。',
          '出来上がった肉じゃがを一緒に食べながら、ふと私は気づいた。味の違いは、レシピの正確さや調理技術の問題ではないのかもしれない。母が30年以上、毎日毎日家族のために料理を作り続けてきた長年の経験と、家族の健康や笑顔を思う深い愛情が、この優しくて温かい味を作り出しているのだ。技術や分量では測れない何かが、確かに存在する。',
          'その夜、食後のお茶を飲みながら、母は穏やかに言った。「あなたも、いつか自分の大切な家族のために料理を作る日が来るわ。何年も作り続けているうちに、自然とあなたなりの『家族の味』ができていくのよ。私の味を真似する必要はないの。あなたの味でいいのよ」',
          '母の優しい言葉に、私は少し救われた気がした。母の味を完璧に再現することが目標ではなく、いつか私自身の心のこもった味を作っていくこと。それこそが大切なのだと、ようやく理解できた。でも、それでも時々、無性に母の肉じゃがが食べたくなるのは、きっと一生変わらないだろう。それは、母の愛情の味だから。'],
   qs:[
     {q:'「私」が母の味を再現できない理由は何だと気づいたか。', opts:['調味料が違うから','料理の技術が足りないから','長年の経験と家族への思いが味を作っているから','レシピが間違っているから'], a:2, type:'alasan', d:'第3段落で「母が何十年も家族のために作り続けてきた経験と、家族を思う気持ちが、この味を作り出している」と述べられています。'},
     {q:'母が伝えたかったことは何か。', opts:['母の味を完璧に再現すべきだ','料理をする必要はない','外食の方が良い','自分なりの家族の味を作っていくことが大切だ'], a:3, type:'detail', d:'母は「あなたなりの『家族の味』ができる」と言い、それを「私」も理解しています。'},
     {q:'この物語が伝えたいテーマは何か。', opts:['料理の技術の重要性','レシピの正確さ','家族への思いが料理の味を作ること','一人暮らしの大変さ'], a:2, type:'mainidea', d:'物語全体を通して、料理の味は技術だけでなく、家族への思いや経験によって作られることが描かれています。'},
   ]},
  {id:'r30', lv:'N2', kind:'主張理解・長文', title:'父が遺した言葉', src:'rbnhd/jlpt-n2-reading #027',
   paras:['父が亡くなって一年が経った。ようやく気持ちの整理がついてきた頃、実家の押し入れで遺品整理をしていた時、古い革表紙の手帳が出てきた。手に取って開いてみると、そこには父の几帳面な文字で日記が細かく綴られていた。几帳面な性格だった父らしく、20年以上にわたって毎日欠かさず書かれている。',
          '私は思わず時間を忘れて夢中でページをめくった。そこには、私がこれまでまったく知らなかった父の本当の姿があった。仕事での理不尽な上司との葛藤、リストラの不安、家族への深い愛情と同時に父親として自信が持てない苦悩、老後や健康への不安。父はいつも強く頼れる、決して弱音を吐かない存在だと思っていたが、実は私と同じように多くの悩みや葛藤を抱えながら、必死に生きていたのだと知った。',
          '特に心に深く刺さったのは、私が高校受験に失敗した時の記述だった。当時15歳の私は、第一志望の高校に不合格となり、部屋に閉じこもって泣いていた。父は私の部屋に来て、肩を叩きながら「次があるさ。人生、一度の失敗くらいで終わりじゃない」と明るく励ましてくれた。私はその言葉に救われた。',
          'しかし日記には、こう書かれていた。「息子が落ち込んで涙を流している姿を見るのは、自分の心が引き裂かれるほど辛い。何とかしてやりたいが、これは息子自身が乗り越えなければならない試練だ。でも、この挫折の経験が将来必ず大きな力になると信じている。今、親として私ができることは、そっと見守り、信じて待つことしかない。息子よ、お前は強い子だ。必ず立ち直れる」',
          '涙が止まらなかった。あの時の父の明るい笑顔、励ましの言葉の裏には、こんな深い思いが隠されていたのか。息子の苦しみを自分のことのように感じながらも、あえて手を出さず見守る。その辛さはどれほどのものだっただろう。私は父の本当の強さが、決して悩みや不安、苦しみがないことではなく、それらをすべて抱えながらも家族のために前を向き続ける力だったのだと、初めて深く理解した。',
          '日記の最後のページ、父が亡くなる3日前に書かれた言葉には、こうあった。「人生には決まった正解などない。迷い、悩み、時には大きな失敗をすることもあるだろう。しかし、それこそが人間として生きるということなのだ。大切なのは、何度転んでも諦めずに立ち上がり、自分の信じる道を一歩ずつ歩み続けることだ。完璧な人生など誰にもない。ただ、後悔のないよう、精一杯生きることだ」',
          'この言葉は、まるで私へ最後のメッセージのように感じられた。父は生前、多くを語らず、自分の感情をあまり表に出さない人だった。しかし、この日記を通して、父が息子に伝えたかった人生の知恵、生きる勇気が痛いほどよく分かった。',
          '今、私は父と同じ45歳になった。仕事でも家庭でも、父が経験したであろう様々な困難や葛藤に日々直面している。プロジェクトの失敗、部下との人間関係、思春期を迎えた娘との会話の難しさ。そんな時、私は父の古い日記をそっと開く。そこには、人生の先輩としての父の深い知恵と、息子を心から愛し信じる父の温かい愛情が詰まっている。',
          '父の言葉は、今も私の人生の道しるべとなっている。完璧な人間など誰一人としていない。みんな悩みながら、迷いながら、それでも一生懸命に生きている。そのことを身をもって教えてくれた父に、今は心の底から感謝している。父が私に遺してくれたものは、お金や財産ではなく、どんな困難にも負けずに生きる勇気と、人を信じる心だった。それは何にも代えがたい、最高の遺産である。'],
   qs:[
     {q:'「私」が父の日記から知ったこととして正しいものはどれか。', opts:['父は悩みや葛藤がなかった','父は受験の失敗を喜んでいた','父は多くの葛藤を抱えながら生きていた','父は日記を書いていなかった'], a:2, type:'detail', d:'第2段落で「実は多くの葛藤を抱えながら生きていたのだ」と述べられています。'},
     {q:'「私」が理解した父の強さとは何か。', opts:['悩みを抱えながらも前を向き続ける力','問題から逃げること','感情を表に出さないこと','悩みや不安がないこと'], a:0, type:'detail', d:'第4段落で「悩みや不安がないことではなく、それらを抱えながらも前を向き続ける力」と理解しています。'},
     {q:'この物語が最も伝えたいメッセージは何か。', opts:['日記を書くことの大切さ','完璧な人間を目指すべきだ','悩みながらも諦めずに生きることの価値','財産を残すことが重要だ'], a:2, type:'mainidea', d:'父の言葉「諦めずに自分の道を歩み続けること」と、最後の「父が遺してくれたものは、生きる勇気だった」に集約されています。'},
   ]},
  {id:'r31', lv:'N2', kind:'内容理解・中文', title:'言語習得と年齢の関係', src:'rbnhd/jlpt-n2-reading #028',
   paras:['外国語を学習する際、年齢が重要な要因となることは広く知られている。一般的に、子供の方が大人よりも言語習得が早く、特に発音はネイティブに近いレベルに達しやすいと言われているが、その科学的な理由は何だろうか。また、大人には本当に言語習得の可能性がないのだろうか。',
          '脳科学の研究によると、子供の脳は大人よりも可塑性が高く、つまり柔軟で、新しい情報や刺激を驚くほどのスピードで吸収しやすい状態にある。特に発音に関しては、幼少期、できれば10歳までに学習を始めた方が、ネイティブスピーカーとほぼ区別がつかない発音を獲得できる可能性が高い。これは、脳の音韻処理能力が思春期前後、およそ12〜15歳頃までに固定されてしまうためだと考えられている。この時期を過ぎると、新しい音を聞き分けたり、正確に発音したりする能力が徐々に低下していく。',
          'しかし、だからといって大人の言語学習に意味がないわけでは決してない。実は大人の学習にも大きな利点がいくつもある。大人は論理的思考力や分析力が十分に発達しており、複雑な文法規則やルールを体系的に理解し、効率的に覚えることができる。また、既に母語という言語の知識体系をしっかりと持っているため、新しい言語の構造を母語と比較対照しながら、理論的に学習を進められる。さらに、「仕事で使いたい」「海外旅行を楽しみたい」など明確な学習目的や動機を持っているため、モチベーションを自己管理しながら維持しやすいという大きな利点もある。',
          '重要なのは、年齢に関わらず、その年代の特性に合った適切な学習方法を選び、継続することだ。子供には歌やゲーム、絵本などを通じた楽しく自然な学習環境が最も効果的である一方、大人には文法や語彙の理論的な説明と、実際の会話やライティングなどの実践的な練習をバランス良く組み合わせた学習法が有効だと言える。年齢は確かに一つの要素だが、それがすべてではない。学習への意欲と適切な方法があれば、いくつになっても言語は習得できるのである。'],
   qs:[
     {q:'子供が発音習得に有利な理由は何か。', opts:['学習時間が長いから','論理的思考力があるから','文法規則を理解できるから','脳の音韻処理能力が思春期までに固定されるから'], a:3, type:'alasan', d:'第2段落で「脳の音韻処理能力が思春期までに固定されるため」と説明されています。'},
     {q:'大人の言語学習の利点として述べられていないものはどれか。', opts:['論理的思考力がある','明確な学習目的を持っている','文法を体系的に理解できる','発音がネイティブと同じになる'], a:3, type:'negasi', d:'発音に関しては、子供の方が有利だと述べられています。大人の利点としては言及されていません。'},
     {q:'筆者が最も伝えたいことは何か。', opts:['子供だけが言語を学ぶべきだ','大人は言語を学べない','年齢に関わらず、適切な方法で学ぶことが大切だ','発音だけが重要だ'], a:2, type:'mainidea', d:'最後の段落で「年齢に関わらず、適切な学習方法を選ぶことが重要」と結論づけています。'},
   ]},
  {id:'r32', lv:'N2', kind:'主張理解・長文', title:'記憶のメカニズムと学習効率', src:'rbnhd/jlpt-n2-reading #030',
   paras:['人間の記憶は、脳内で複雑なプロセスを経て形成される。記憶のメカニズムを理解することは、効率的な学習方法を見つける上で極めて重要である。近年の脳科学の研究により、記憶の仕組みが次第に明らかになってきており、その知見を活用することで、学習効率を飛躍的に向上させることができるようになってきた。',
          '記憶には、大きく分けて短期記憶と長期記憶の2種類がある。短期記憶は、一時的に情報を保持するもので、容量が非常に限られており、通常は数秒から数十秒程度しか保持できない。電話番号を覚えて、すぐにダイヤルするような場合がこれにあたる。心理学者ミラーの研究によれば、人間が一度に記憶できる情報の単位は平均して7つ程度、つまり「マジカルナンバー7」と呼ばれる範囲内だとされている。一方、長期記憶は、数時間から一生涯にわたって保存される情報で、容量はほぼ無限だと考えられている。私たちの知識や経験、技能などは、すべてこの長期記憶に蓄えられている。学習において最も重要な課題は、いかに情報を短期記憶から長期記憶へと効率的に移行させるかということである。',
          'この移行を促進する鍵となるのが「反復」と「関連付け」だ。脳科学の研究によると、同じ情報を繰り返し学習することで、脳内のシナプス結合、つまり神経細胞同士のつながりが強化され、記憶が確実に定着しやすくなる。ただし、ただ機械的に繰り返すだけでは効果は限定的だ。ドイツの心理学者エビングハウスの「忘却曲線」の研究が示すように、人間は学習した内容を時間の経過とともに急速に忘れていく。しかし、適切な間隔を空けて復習する「分散学習」を行うことで、記憶の定着率を大幅に高めることができる。例えば、学習した翌日、1週間後、1ヶ月後というように、徐々に間隔を広げながら復習することが、集中的に何時間も勉強するよりもはるかに効果的なのである。',
          'また、新しい情報を既存の知識や経験と関連付けることも極めて効果的だ。人間の脳は、孤立した意味のない情報よりも、既に持っている知識と結びついた、意味のあるつながりを持った情報の方が圧倒的に記憶しやすい構造になっている。例えば、歴史の年号を覚える際、単なる数字の羅列として機械的に暗記しようとするよりも、その出来事の歴史的背景や前後の因果関係、他の出来事との関連性と結びつけて理解した方が、記憶に深く残りやすい。これは「精緻化リハーサル」と呼ばれる記憶戦略である。',
          'さらに、感情と強く結びついた記憶は特に鮮明に長く残る傾向がある。楽しかった出来事や、強い印象を受けた経験、感動した場面などは何年経っても忘れにくいのはこのためだ。脳の中で感情を司る扁桃体という部分が活性化すると、記憶を司る海馬の働きが強化されることが分かっている。学習においても、興味や関心、好奇心を持って能動的に取り組むことで、記憶の定着が大きく促進される。逆に、義務感や強制感だけで受動的に学習を続けても、脳は十分に活性化せず、効率は上がらない。',
          '睡眠も記憶の定着に極めて重要な役割を果たしている。睡眠中、特にレム睡眠の段階で、脳は日中に得た情報を整理し、重要なものを選別して長期記憶として固定する作業を活発に行っている。この過程は「記憶の固定化(consolidation)」と呼ばれる。十分な質の良い睡眠を取らないと、せっかく時間をかけて学習した内容も脳に定着しにくくなってしまう。実際、試験前の徹夜勉強は、短期的には知識を詰め込めるように感じるが、長期的な記憶の定着という観点からは非効率であることが、多くの研究で証明されている。',
          '効率的な学習とは、単に長時間机に向かうことではなく、これらの記憶のメカニズムを正しく理解し、それに基づいた科学的な方法を実践することなのだ。闇雲に何時間も勉強するのではなく、分散学習、関連付け、感情の活用、十分な睡眠といった、脳科学的な裏付けのある方法で計画的に学習することが、真の学力向上と知識の定着につながるのである。'],
   qs:[
     {q:'短期記憶と長期記憶の違いとして正しいものはどれか。', opts:['短期記憶の容量は無限で、長期記憶は限られている','短期記憶は一時的で容量が限られ、長期記憶は長期間保存される','両方とも同じ性質を持つ','長期記憶の方が容量が小さい'], a:1, type:'detail', d:'第2段落で「短期記憶は、一時的に情報を保持するもので、容量が限られている」「長期記憶は、長期間保存される情報」と説明されています。'},
     {q:'記憶の定着を促進する方法として述べられていないものはどれか。', opts:['できるだけ早く忘れる','既存の知識と関連付ける','間隔を空けて復習する','十分な睡眠を取る'], a:0, type:'negasi', d:'「早く忘れる」ことは記憶の定着とは逆の行為で、述べられていません。'},
     {q:'筆者が最も強調していることは何か。', opts:['長時間勉強することが最も重要だ','記憶のメカニズムを理解し、科学的な方法で学習すべきだ','睡眠は不要である','感情は学習に関係ない'], a:1, type:'mainidea', d:'最終段落で「記憶のメカニズムを理解し、それに基づいた方法を実践すること」「科学的な裏付けのある方法で学習すること」が重要だと述べられています。'},
   ]},
  {id:'r33', lv:'N2', kind:'内容理解・短文', title:'システム障害のお詫びとお知らせ', src:'rbnhd/jlpt-n2-reading #032',
   paras:['お客様各位',
          '平素より弊社サービスをご利用いただき、誠にありがとうございます。',
          '11月20日（水）14時30分頃から17時45分頃まで、本番環境においてシステム障害が発生し、サービスをご利用いただけない状態となりました。ご利用のお客様には多大なるご迷惑をおかけしましたことを、深くお詫び申し上げます。',
          '【障害の概要】<br>・発生日時：11月20日 14:30〜17:45（約3時間15分）<br>・影響範囲：全ユーザー<br>・症状：ログインができない、データの読み込みに失敗する',
          '【原因】<br>データベースサーバーの容量不足により、処理が正常に行えなくなりました。',
          '【対応】<br>緊急でサーバーの増設を行い、現在は復旧しております。今後同様の障害が発生しないよう、監視体制を強化いたします。',
          '本障害の影響でお客様のデータが消失することはございません。ご安心ください。',
          'ご不明な点がございましたら、サポート窓口までお問い合わせください。'],
   qs:[
     {q:'システム障害の原因は何でしたか。', opts:['ネットワークの切断','データベースサーバーの容量不足','サイバー攻撃','プログラムのバグ'], a:1, type:'alasan', d:'「データベースサーバーの容量不足により、処理が正常に行えなくなりました」と原因が明記されています。'},
     {q:'今後の対策として、会社は何をすると言っていますか。', opts:['全ユーザーにお金を返す','料金を値下げする','サービスを終了する','監視体制を強化する'], a:3, type:'detail', d:'「今後同様の障害が発生しないよう、監視体制を強化いたします」と書かれています。'},
   ]},
  {id:'r34', lv:'N2', kind:'主張理解・長文', title:'エンジニア採用についての考え方', src:'rbnhd/jlpt-n2-reading #033',
   paras:['当社のエンジニア採用に関して、私が大切にしている考え方をお伝えしたい。',
          '多くの企業が即戦力を求める一方で、私は「成長の可能性」を何より重視している。技術は日進月歩で変化する。今日の最新技術が、来年には時代遅れになることも珍しくない。だからこそ、特定の技術に詳しいかどうかよりも、新しいことを学ぶ姿勢があるかどうかを見ている。',
          'コードレビューの経験から言えば、優れたエンジニアには共通点がある。それは「なぜそう書いたのか」を説明できることだ。単にコードが動けばいいというわけではない。チームで開発する以上、他のメンバーが理解できるコードを書く必要がある。そのためには、自分の判断の根拠を言語化する力が欠かせない。',
          '面接では、必ず「最近学んだこと」について聞くようにしている。技術的負債の解消に取り組んだ話、新しいフレームワークを導入した話など、内容は何でもいい。大切なのは、なぜそれを学ぼうと思ったのか、学んでみてどう感じたのかを自分の言葉で語れるかどうかだ。',
          'もう一つ重視しているのは、失敗の経験だ。障害対応で徹夜した話、リリース後にバグが発覚して冷や汗をかいた話。こうした経験を素直に話せる人は、失敗から学ぶ姿勢を持っている。本番環境で障害が起きないに越したことはないが、万が一の時に冷静に対応できるかどうかは、過去の経験に大きく左右される。',
          'チームへの貢献意識も見ている。どんなに優秀でも、一人で抱え込むタイプは採用をためらう。報連相を怠らず、困ったときに「助けて」と言える人。そういう人がいるチームは、全体として強くなれる。',
          '技術力は入社後にいくらでも伸ばせる。しかし、学ぶ姿勢やコミュニケーション能力は、短期間で身につくものではない。だからこそ、採用の時点でそこを見極めることが重要だと考えている。',
          'エンジニア不足が叫ばれる中、採用基準を下げたい誘惑にかられることもある。しかし、チームの文化は一人ひとりの採用によって作られる。妥協せずに良い人材を探し続けることが、長い目で見れば会社の成長につながると信じている。'],
   qs:[
     {q:'筆者が採用で最も重視していることは何ですか。', opts:['特定の技術への深い知識','即戦力として働ける経験','有名企業での勤務経験','新しいことを学ぶ姿勢'], a:3, type:'detail', d:'「特定の技術に詳しいかどうかよりも、新しいことを学ぶ姿勢があるかどうかを見ている」と筆者は述べています。'},
     {q:'筆者が面接で「最近学んだこと」を聞く理由は何ですか。', opts:['技術的な知識の量を測るため','自分の言葉で学びを語れるか見るため','どの会社で働いていたか確認するため','面接の時間を埋めるため'], a:1, type:'alasan', d:'「なぜそれを学ぼうと思ったのか、学んでみてどう感じたのかを自分の言葉で語れるかどうか」が大切だと述べています。'},
     {q:'筆者が採用をためらうのはどのような人ですか。', opts:['失敗の経験がある人','一人で抱え込むタイプの人','障害対応の経験がない人','新しい技術を知らない人'], a:1, type:'detail', d:'「どんなに優秀でも、一人で抱え込むタイプは採用をためらう」と明確に述べています。'},
   ]},
  {id:'r35', lv:'N2', kind:'内容理解・中文', title:'生成AIとエンジニアの仕事', src:'rbnhd/jlpt-n2-reading #034',
   paras:['生成AIの登場により、多くの職業が変化しつつある。特にプログラマーの仕事は大きな影響を受けている。',
          'AIがコードを自動生成できるようになった今、「プログラマーは不要になるのではないか」という議論をよく耳にする。確かに、簡単なコードであればAIでも書ける。しかし、だからといってプログラマーの仕事がなくなるわけではない。',
          'AIが生成したコードをそのまま使えることは稀だ。多くの場合、文脈に合わせた修正が必要になる。AIはあくまでツールであり、最終的な判断は人間が行わなければならない。「このコードは本番環境で安全に動くか」「パフォーマンスに問題はないか」「セキュリティ上のリスクはないか」——こうした確認ができるのは、経験を積んだエンジニアだけだ。',
          'むしろ、AIを上手に活用できるエンジニアの価値は高まっている。AIに適切な指示を出し、生成されたコードを評価し、改善できる人材は、これからますます重宝されるだろう。',
          '一方で、単純な作業だけをしていた人は厳しい立場に置かれる可能性がある。AIに代替されないためには、設計能力やコミュニケーション能力など、人間にしかできない部分を磨く必要がある。',
          '結局のところ、AIは敵ではなく味方だ。上手に付き合えば、生産性を何倍にも高めることができる。変化を恐れるのではなく、新しいツールとして積極的に取り入れる姿勢が大切だ。'],
   qs:[
     {q:'筆者によると、AIが生成したコードについてどのようなことが言えますか。', opts:['そのまま本番環境で使える','プログラマーより質が高い','セキュリティ上の問題がない','多くの場合、修正が必要になる'], a:3, type:'detail', d:'「AIが生成したコードをそのまま使えることは稀だ。多くの場合、文脈に合わせた修正が必要になる」と述べています。'},
     {q:'筆者が「価値が高まる」と言っているのは、どのようなエンジニアですか。', opts:['AIの開発に携わるエンジニア','AIを使わずに全て自分で書くエンジニア','単純な作業を素早くこなすエンジニア','AIに適切な指示を出し、結果を評価できるエンジニア'], a:3, type:'detail', d:'「AIに適切な指示を出し、生成されたコードを評価し、改善できる人材は、これからますます重宝されるだろう」と述べています。'},
     {q:'筆者のAIに対する考え方として最も適切なものはどれですか。', opts:['AIは危険なので使うべきではない','AIは敵ではなく、積極的に活用すべきだ','AIがあればプログラマーは不要になる','AIより人間の方が常に優れている'], a:1, type:'detail', d:'「AIは敵ではなく味方だ」「新しいツールとして積極的に取り入れる姿勢が大切だ」と結論づけています。'},
   ]},
  {id:'r36', lv:'N2', kind:'内容理解・中文', title:'日本のIT企業文化について', src:'rbnhd/jlpt-n2-reading #036',
   paras:['日本のIT企業で働き始めて3年になる。母国のスタートアップで5年間エンジニアとして働いた経験があるが、日本の職場文化には驚くことが多かった。',
          'まず、会議の進め方が違う。母国では、会議中に自分の意見をどんどん言うのが当たり前だった。しかし日本では、事前に根回しをして、会議は確認の場という位置づけのことが多い。最初は「なぜ会議で誰も反対しないのだろう」と不思議に思ったが、実は会議の前に個別に話し合いが行われていたのだ。',
          '報連相の文化も印象的だ。小さなことでも上司に報告し、困ったことがあれば早めに相談する。母国では「自分で解決できることは自分でやる」という考え方が強かったので、最初は過剰に感じた。しかし、この習慣のおかげでチーム全体の状況が把握しやすく、問題が大きくなる前に対処できることに気づいた。',
          '一方で、意思決定のスピードには課題を感じることもある。新しいツールを導入したくても、稟議を通すのに時間がかかる。スタートアップでは「まず試して、だめなら変える」が普通だったが、日本の大企業では慎重に検討してから動く傾向がある。',
          'どちらが良い悪いということではない。日本式のやり方には、リスクを最小限に抑えるという利点がある。大切なのは、文化の違いを理解し、その環境で最大限の成果を出すことだと思う。',
          '今では、根回しの重要性も理解できるようになった。文化の違いを楽しみながら、日本でのエンジニア生活を続けていきたい。'],
   qs:[
     {q:'筆者が日本の会議について最初に不思議に思ったことは何ですか。', opts:['会議の時間が長いこと','会議で誰も反対しないこと','会議に参加者が少ないこと','会議で英語が使われないこと'], a:1, type:'detail', d:'「『なぜ会議で誰も反対しないのだろう』と不思議に思った」と書かれています。これは根回しの文化を知らなかったためです。'},
     {q:'筆者が報連相の文化について、後で気づいた利点は何ですか。', opts:['問題が大きくなる前に対処できること','上司との関係が良くなること','自分で仕事をしなくて済むこと','会議に出なくてよくなること'], a:0, type:'detail', d:'「この習慣のおかげでチーム全体の状況が把握しやすく、問題が大きくなる前に対処できることに気づいた」と述べています。'},
     {q:'筆者の結論として最も適切なものはどれですか。', opts:['日本の文化より母国の文化の方が優れている','日本の大企業は働きにくい','早く母国に帰りたい','文化の違いを理解し、その環境で成果を出すことが大切だ'], a:3, type:'mainidea', d:'「どちらが良い悪いということではない」「大切なのは、文化の違いを理解し、その環境で最大限の成果を出すことだと思う」と結論づけています。'},
   ]},
  {id:'r37', lv:'N2', kind:'主張理解・長文', title:'地方都市の活性化', src:'rbnhd/jlpt-n2-reading #008',
   paras:['日本の地方都市では、人口減少と高齢化が急速に進んでいる。若者は仕事や進学の機会を求めて都市部へ流出し、残された高齢者だけでは地域経済を支えることができない。商店街はシャッター通りと化し、かつての賑わいは完全に失われてしまった。公共サービスの維持も困難になり、医療機関や学校の閉鎖が相次いでいる。このままでは、地方都市の衰退は止まらない。',
          'こうした深刻な状況を打開するため、各地で様々な取り組みが積極的に行われている。ある地方都市では、IT企業のサテライトオフィス誘致に成功した。都会の喧騒を離れ、自然豊かな環境で働きたいという人々のニーズに応えたのだ。リモートワークの急速な普及により、場所にとらわれない働き方が可能になったことも追い風となった。高速インターネット環境の整備や、コワーキングスペースの設置など、受け入れ態勢の充実も功を奏している。',
          'また、地域の特産品を活用した観光振興も重要な戦略だ。単に観光地を整備するだけでなく、体験型の観光プログラムを充実させることで、滞在時間を延ばし、地域への経済効果を最大化している。農業体験や伝統工芸の体験教室、地元の食材を使った料理教室などは、特に外国人観光客に人気があり、リピーターも増えている。SNSを活用した情報発信により、これまで知られていなかった魅力が広く伝わるようになった。',
          'さらに、空き家を活用した移住促進策も注目されている。都市部での生活に疲れた人々に、ゆったりとした田舎暮らしの魅力を発信し、移住を手厚くサポートする。空き家をリノベーションして格安で提供したり、就農支援や起業支援を行ったりすることで、新たな住民を呼び込んでいる。移住者同士の交流会や、地域住民との懇親会も定期的に開催され、スムーズな定着を促している。',
          'しかし、これらの取り組みにも課題はある。一時的なブームに終わらせないためには、継続的な努力と工夫が不可欠だ。また、地域住民の理解と積極的な協力なくしては、真の活性化は実現しない。新旧住民の交流を促進し、共に地域を作り上げていくという意識を育てることが何より重要である。行政だけでなく、住民一人一人が当事者意識を持つ必要がある。',
          '地方都市の活性化は、日本全体の持続可能性に関わる重要な課題でもある。都市と地方のバランスの取れた発展なくして、真に豊かな社会は実現できない。それぞれの地域が持つ独自の魅力を最大限に活かし、画一的ではない多様性のある社会を目指すべきだ。地方創生は、日本の未来を左右する鍵となるだろう。'],
   qs:[
     {q:'IT企業のサテライトオフィス誘致が成功した背景として挙げられていないものはどれか。', opts:['自然豊かな環境への需要','リモートワークの普及','税制優遇措置','場所にとらわれない働き方'], a:2, type:'negasi', d:'税制優遇措置については文章中で言及されていません。'},
     {q:'地域活性化の課題として述べられているものはどれか。', opts:['外国人観光客が少ないこと','特産品がないこと','空き家が不足していること','継続的な努力と地域住民の協力が必要なこと'], a:3, type:'detail', d:'第5段落で「継続的な努力と工夫が不可欠」「地域住民の理解と積極的な協力なくしては、真の活性化は実現しない」と述べられています。'},
     {q:'筆者の結論として最も適切なものはどれか。', opts:['都市部への人口集中は避けられない','地方都市は観光業に特化すべきだ','すべての地方都市で同じ対策を実施すべきだ','地域の魅力を活かし多様性のある社会を目指すべきだ'], a:3, type:'mainidea', d:'最終段落で「それぞれの地域が持つ独自の魅力を最大限に活かし、画一的ではない多様性のある社会を目指すべきだ」と結論づけています。'},
   ]},
  {id:'r38', lv:'N2', kind:'統合理解 (A/B)', title:'オンライン教育の効果', src:'rbnhd/jlpt-n2-reading #011',
   paras:['【研究報告A：大学教育研究所】<br>オンライン教育の効果に関する最新の研究では、全国の大学生5000名を対象とした調査の結果、従来の対面授業と比較して学習効果に統計的に有意な差はないことが明らかになった。それどころか、いくつかの側面ではオンライン教育の方が優れている可能性が示された。',
          '具体的には、学習者が自分のペースで進められる点、理解が不十分な箇所を繰り返し視聴できる点、移動時間がかからず効率的である点などが高く評価された。特に、数学や物理などの基礎知識の習得においては、オンライン教育の方が平均点が8.5％高いという結果が出ている。また、オンデマンド形式の授業では、学生の集中力が維持されやすく、復習の頻度も対面授業の1.7倍に達した。さらに、質問をチャットで送れるシステムは、対面では質問しにくいと感じる学生にとって有効であることも分かった。',
          '【教師の意見B：高校教諭・田中先生】<br>私は20年間教壇に立ってきた経験から、オンライン教育には大きな課題があると考えています。確かにコロナ禍で急速に普及し、便利な面もありますが、教育の本質的な部分が欠けているのではないでしょうか。',
          '対面授業では、生徒の表情、視線、姿勢、小さなつぶやきなど、言葉にならない情報から理解度を瞬時に判断し、説明のスピードや方法を柔軟に調整できます。しかし、オンラインでは画面越しにしかコミュニケーションが取れず、このような細やかな対応が極めて困難です。実際、私のクラスでオンライン授業を行った際、理解できていないのに「分かった」と答える生徒が増えました。',
          'また、生徒同士の自然な対話や議論、グループワークでの協力も、対面の方が圧倒的にスムーズです。教育は単なる知識の伝達ではありません。他者と協力する力、意見を調整する能力、社会性やコミュニケーション能力の育成も、教育の重要な役割です。これらはオンラインでは十分に養えないと私は考えます。技術の進歩は素晴らしいですが、人間と人間が直接向き合う価値を忘れてはならないのです。'],
   qs:[
     {q:'研究報告Aと教師の意見Bで共通して認めている点は何か。', opts:['教育方法にはそれぞれ特徴がある','オンライン教育は完全に対面授業に劣る','対面授業は不要である','オンライン教育は基礎知識の習得に適さない'], a:0, type:'togou', d:'両者とも、それぞれの教育方法に長所と短所があることを認識しています。'},
     {q:'教師が対面授業の利点として挙げていないものはどれか。', opts:['生徒の理解度を把握しやすい','生徒同士の議論がしやすい','繰り返し学習できる','社会性の育成ができる'], a:2, type:'detail', d:'繰り返し学習できることは、研究報告Aでオンライン教育の利点として挙げられています。'},
   ]},
  {id:'r39', lv:'N2', kind:'情報検索', title:'温泉旅館の宿泊プラン', src:'rbnhd/jlpt-n2-reading #014',
   paras:['【山の湯温泉　春の特別プラン　ご案内】',
          '創業100年の歴史を誇る当館では、四季折々の自然を楽しみながら、源泉掛け流しの天然温泉をお楽しみいただけます。今春も皆様に喜んでいただけるお得なプランをご用意いたしました。',
          '■桜満喫プラン（期間限定：3/25～4/15）<br>・1泊2食付き：15,000円～（お一人様、税込）<br>・桜の見える特別室を確約（和室10畳、露天風呂付き）<br>・夕食時、地元銘酒「山桜」1本サービス<br>・料理長特製の季節会席料理（桜鯛、山菜天ぷら等）<br>・早朝桜見物ツアー付き（午前6:30出発、希望者のみ、ガイド同行）<br>・桜まんじゅうのお土産付き',
          '■ファミリープラン（通年ご利用可）<br>・大人（中学生以上）：12,000円<br>・小学生：6,000円（大人料金の50％）<br>・幼児（3歳～6歳未満）：3,000円（食事・布団付き）<br>・幼児（3歳未満）：無料（食事・布団なし）<br>※和室12畳のゆったりしたお部屋、最大5名様まで<br>※お子様用浴衣、歯ブラシ、タオル等のアメニティ完備<br>※夕食は個室食事処にてご用意、お子様ランチもご用意できます<br>※キッズスペース、絵本コーナーあり',
          '■ビジネスプラン（平日限定、土日祝除く）<br>・素泊まり：6,500円<br>・朝食付き：7,800円（和定食または洋定食）<br>・2連泊以上でご利用の場合、10％割引適用<br>・チェックイン14:00、チェックアウト12:00まで延長可能<br>（通常プランはチェックイン15:00、チェックアウト10:00）<br>・全室Wi-Fi完備、ワークデスク・コンセント充実<br>・ズボンプレッサー、アイロン貸出無料',
          '■日帰り入浴のご案内<br>・大人（中学生以上）：1,200円<br>・小人（3歳～小学生）：600円<br>・営業時間：11:00～20:00（最終受付19:30）<br>・タオルセット（バスタオル+フェイスタオル）：300円<br>・休憩室、食事処もご利用いただけます<br>・毎月第2・第4月曜日は設備点検のため休業',
          '【ご予約・お問い合わせ】<br>電話：0XXX-XX-XXXX（受付時間：9:00～21:00、年中無休）<br>ホームページ：www.yamanoyu-onsen.jp（24時間予約受付）<br>メール：info@yamanoyu-onsen.jp',
          '※キャンセル料について<br>・3日前まで：無料<br>・2日前：宿泊料金の20％<br>・前日：宿泊料金の50％<br>・当日および無連絡キャンセル：宿泊料金の100％'],
   qs:[
     {q:'4月10日に大人2名と5歳の子供1名で1泊する場合、ファミリープランの合計金額はいくらか。', opts:['27,000円','24,000円','30,000円','36,000円'], a:0, type:'retrieval', d:'大人12,000円×2名＋幼児（3歳以上）3,000円×1名＝27,000円です。'},
     {q:'ビジネスプランで3泊する場合の朝食付き料金はいくらか。', opts:['17,550円','23,400円','21,060円','19,500円'], a:2, type:'retrieval', d:'朝食付き7,800円×3泊＝23,400円、2連泊以上で10％割引なので、23,400円×0.9＝21,060円です。'},
   ]},
  {id:'r40', lv:'N2', kind:'統合理解 (A/B)', title:'再生可能エネルギーの課題', src:'rbnhd/jlpt-n2-reading #029',
   paras:['【文章A】<br>再生可能エネルギーは、地球温暖化対策の切り札として世界中で期待されている。太陽光発電や風力発電は、化石燃料と違ってCO2をほとんど排出せず、気候変動の抑制に大きく貢献できる。また、太陽や風などの自然資源を利用するため、石油や石炭のように資源が枯渇する心配が全くない。技術の進歩により、発電コストも年々下がっており、すでに一部の地域では火力発電よりも安価になっている。例えば、ドイツは2022年に電力消費の約46%を再生可能エネルギーでまかない、2030年までに80%という野心的な目標を掲げている。また、日本でも2030年度に36〜38%を目指すなど、多くの国が2050年までにカーボンニュートラルを達成するため、再生可能エネルギーへの投資を大幅に拡大している。エネルギーの自給率を高めることは、国際情勢に左右されない安定したエネルギー供給を可能にし、国家の安全保障にも直結する。さらに、再生可能エネルギー産業の発展は、新たな雇用を生み出し、地域経済の活性化にもつながる。これは持続可能な社会を実現するための必然的な流れであり、避けて通れない道なのだ。',
          '【文章B】<br>一方で、再生可能エネルギーには現実的に解決すべき深刻な課題が数多く残されている。最大の問題は、天候や時間帯に大きく左右されるため、安定した電力供給が極めて難しいことだ。太陽が出ていない夜間や曇りの日、雨の日には太陽光発電の出力が大幅に低下し、風が吹かない日には風力発電がほとんど機能しない。このため、火力発電などのバックアップ電源を常に待機させておく必要があり、完全に化石燃料から脱却することが困難になっている。蓄電技術の開発が世界中で進められているものの、現在主流のリチウムイオン電池は非常にコストが高く、電力会社が大規模に導入するには莫大な投資が必要となる。また、大規模な太陽光パネルや風力発電施設の設置には広大な土地が必要で、日本のように国土が限られ、山がちな地形の国では、適切な設置場所の確保自体が大きな課題だ。実際、山林を切り開いて太陽光パネルを設置した結果、土砂災害のリスクが高まったり、貴重な自然環境や景観が損なわれたりする事例が各地で報告されている。さらに、急速に増加する再生可能エネルギーを既存の送電網に統合することも、電圧の変動や周波数の調整など、技術的に難しい課題となっている。理想と現実のギャップを埋めるには、技術開発、インフラ整備、法制度の改革など、まだ多くの困難を乗り越える必要がある。'],
   qs:[
     {q:'文章Aと文章Bの共通認識は何か。', opts:['再生可能エネルギーは完璧である','化石燃料の方が優れている','再生可能エネルギーは不要である','再生可能エネルギーは重要なテーマである'], a:3, type:'togou', d:'両者とも再生可能エネルギーについて論じており、その重要性は認識しています。ただし評価が異なります。'},
     {q:'文章Bで指摘されている最大の課題は何か。', opts:['天候に左右され、安定供給が難しい','CO2を排出する','発電コストが高い','技術が古い'], a:0, type:'detail', d:'文章Bで「最大の問題は、天候に左右されるため、安定した電力供給が難しいこと」と明記されています。'},
   ]},
  {id:'r41', lv:'N2', kind:'情報検索', title:'リモートワークの社内ガイドライン', src:'rbnhd/jlpt-n2-reading #031',
   paras:['【リモートワーク実施要綱】',
          '１．対象者<br>原則として、入社６か月以上の正社員とする。ただし、上長の承認があれば、契約社員も対象となる。',
          '２．実施日数<br>週に２日まで在宅勤務が可能。ただし、チームミーティングがある日は原則出社とする。スプリントの振り返りミーティングは毎週金曜日に実施のため、金曜日は出社日とする。',
          '３．勤務時間<br>コアタイムは10時から15時とし、この時間帯は必ずオンラインで連絡が取れる状態にすること。始業・終業時刻は各自のSlackステータスで明示すること。',
          '４．セキュリティ<br>・会社支給のVPNを必ず使用すること<br>・カフェなど公共の場所での作業時は、のぞき見防止フィルターを使用すること<br>・機密情報を含むファイルは、ローカルに保存せず、社内クラウドストレージを使用すること',
          '５．申請方法<br>在宅勤務を行う場合は、前日17時までに社内システムから申請し、上長の承認を得ること。急な申請の場合は、Slackで上長に直接連絡すること。',
          '本ガイドラインに関するお問い合わせは、人事部（内線：2345）までご連絡ください。'],
   qs:[
     {q:'入社４か月の契約社員の田中さんがリモートワークをしたい場合、どうすればよいですか。', opts:['上長に承認をもらう','人事部に相談する','入社６か月になるまで待つ','契約社員は対象外なのでリモートワークできない'], a:0, type:'retrieval', d:'対象者の項目で「上長の承認があれば、契約社員も対象となる」と書かれています。田中さんは入社６か月未満ですが、契約社員でも上長の承認があれば可能です。'},
     {q:'このガイドラインによると、毎週金曜日に出社が必要な理由は何ですか。', opts:['コアタイムが金曜日だけ長いから','セキュリティチェックがあるから','上長への申請締め切りだから','スプリントの振り返りミーティングがあるから'], a:3, type:'retrieval', d:'「スプリントの振り返りミーティングは毎週金曜日に実施のため、金曜日は出社日とする」と明記されています。'},
     {q:'カフェで仕事をする場合、セキュリティのために何をする必要がありますか。', opts:['機密情報をローカルに保存する','VPNを使わずに作業する','のぞき見防止フィルターを使用する','上長に直接電話で報告する'], a:2, type:'retrieval', d:'セキュリティの項目で「カフェなど公共の場所での作業時は、のぞき見防止フィルターを使用すること」と書かれています。'},
   ]},
  {id:'r42', lv:'N2', kind:'統合理解 (A/B)', title:'開発チームの振り返りミーティング', src:'rbnhd/jlpt-n2-reading #035',
   paras:['【文章A：今週のスプリント振り返り議事録】',
          '日時：11月22日（金）16:00-17:00<br>参加者：山田（SM）、佐藤、田中、鈴木',
          '■ よかったこと（Keep）<br>・新機能のデプロイが予定通り完了した<br>・コードレビューの待ち時間が先週より改善された<br>・ペアプログラミングの導入で知識共有が進んだ',
          '■ 改善したいこと（Problem）<br>・テスト環境のビルドが不安定で、何度もやり直しが発生した<br>・仕様変更の共有が遅れ、手戻りが発生した<br>・障害対応で予定外の作業が入り、他のタスクが遅れた',
          '■ 次に試すこと（Try）<br>・テスト環境のDockerイメージを作り直す（担当：鈴木）<br>・仕様変更はSlackの専用チャンネルで即時共有する<br>・オンコール担当を明確にし、他メンバーの作業を守る',
          '---',
          '【文章B：鈴木さんの日報より】',
          '今日の振り返りミーティングで、テスト環境の問題について話し合った。ビルドが不安定な原因を調べたところ、依存ライブラリのバージョンがローカルと本番で違っていることがわかった。来週、Dockerイメージを作り直して、環境差異をなくす予定だ。',
          '正直なところ、この問題は以前から気づいていたが、優先度が低いと思って後回しにしていた。しかし、今週だけで3回もビルドが失敗し、チーム全体で2時間以上のロスが出た。技術的負債は早めに返済すべきだと改めて実感した。',
          '来週は、まずDockerfileの見直しから始める。金曜日までには新しい環境を用意したい。'],
   qs:[
     {q:'テスト環境のビルドが不安定だった原因は何ですか。', opts:['サーバーの容量不足','依存ライブラリのバージョンの違い','ネットワークの問題','コードレビューの遅れ'], a:1, type:'alasan', d:'文章Bで鈴木さんが「依存ライブラリのバージョンがローカルと本番で違っていることがわかった」と報告しています。'},
     {q:'鈴木さんがこの問題を後回しにしていた理由は何ですか。', opts:['原因がわからなかったから','他のメンバーの担当だと思っていたから','上司から指示がなかったから','優先度が低いと思っていたから'], a:3, type:'alasan', d:'「この問題は以前から気づいていたが、優先度が低いと思って後回しにしていた」と鈴木さんは書いています。'},
     {q:'今回の振り返りで決まった、仕様変更の共有方法は何ですか。', opts:['メールで全員に送る','毎日のミーティングで報告する','議事録に記載して後で確認する','Slackの専用チャンネルで即時共有する'], a:3, type:'detail', d:'文章Aの「次に試すこと」で「仕様変更はSlackの専用チャンネルで即時共有する」と決定しています。'},
   ]},
];

/* ===== Renderer bacaan: feedback instan + mode Sesi 5 Soal Acak ===== */
(function () {
  function el(id) { return document.getElementById(id); }
  function shuffleArr(a) {
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }

  var state = null; // {mode:'read'|'session', items:[{r,qi,order,correct}], answered:{}, score}
  var TOTAL_Q = READING.reduce(function (s, r) { return s + r.qs.length; }, 0);

  function renderMenu() {
    var list = el('readList');
    if (!list) return;
    var html = '<button type="button" class="card tile read-tile" id="btnSession" style="display:block;width:100%;text-align:left;cursor:pointer;border:2px solid #16a34a">'
      + '<div class="row between"><div class="grow">'
      + '<div class="label">🎲 Sesi Latihan Acak</div>'
      + '<div class="mt4"><b>5 soal per sesi</b> dari seluruh database</div>'
      + '<div class="small muted mt4">' + READING.length + ' bacaan · ' + TOTAL_Q + ' soal — soal & opsi diacak tiap sesi</div>'
      + '</div><span class="tag" style="background:#dcfce7;color:#166534">acak</span></div></button>';
    html += READING.map(function (r) {
      return '<button type="button" class="card tile read-tile" data-read-id="' + r.id + '" style="display:block;width:100%;text-align:left;cursor:pointer">'
        + '<div class="row between"><div class="grow">'
        + '<div class="label">' + r.kind + ' · ' + r.lv + '</div>'
        + '<div class="mt4">' + r.title + '</div>'
        + '</div><span class="tag">' + r.qs.length + ' soal</span></div></button>';
    }).join('');
    list.innerHTML = html;
    el('btnSession').addEventListener('click', startSession);
    list.querySelectorAll('[data-read-id]').forEach(function (b) {
      b.addEventListener('click', function () { openReading(b.getAttribute('data-read-id')); });
    });
  }

  function makeItem(r, qi) {
    var q = r.qs[qi];
    var order = shuffleArr(q.opts.map(function (_, i) { return i; })); // posisi tampil -> index opsi asli
    return { r: r, qi: qi, order: order, correct: order.indexOf(q.a) };
  }

  function openReading(id) {
    var r = READING.find(function (x) { return x.id === id; });
    if (!r) return;
    state = { mode: 'read', items: r.qs.map(function (_, qi) { return makeItem(r, qi); }), answered: {}, score: 0 };
    el('readMenu').hidden = true;
    el('readView').hidden = false;
    el('readTitle').innerHTML = r.title;
    el('readMeta').innerHTML = '<span class="tag">' + r.kind + '</span><span class="tag">' + r.lv + '</span><span class="tag" id="readScoreTag"></span>';
    el('readBody').innerHTML = r.paras.map(function (p) { return '<p class="mt8">' + p + '</p>'; }).join('');
    renderItems(false);
    window.scrollTo(0, 0);
  }

  function startSession() {
    var pool = [];
    READING.forEach(function (r) { r.qs.forEach(function (_, qi) { pool.push({ r: r, qi: qi }); }); });
    shuffleArr(pool);
    state = { mode: 'session', items: pool.slice(0, 5).map(function (p) { return makeItem(p.r, p.qi); }), answered: {}, score: 0 };
    el('readMenu').hidden = true;
    el('readView').hidden = false;
    el('readTitle').innerHTML = '🎲 Sesi Latihan — 5 Soal Acak';
    el('readMeta').innerHTML = '<span class="tag">' + READING.length + ' bacaan</span><span class="tag">' + TOTAL_Q + ' soal</span><span class="tag" id="readScoreTag"></span>';
    el('readBody').innerHTML = '<p class="small muted">Tiap soal menampilkan bacaannya. Jawab kelimanya — urutan soal dan opsi diacak untuk sesi ini.</p>';
    renderItems(true);
    window.scrollTo(0, 0);
  }

  function renderItems(withPassage) {
    var quiz = el('readQuiz');
    quiz.innerHTML = state.items.map(function (it, i) {
      var q = it.r.qs[it.qi];
      var head = withPassage
        ? '<div class="label">Soal ' + (i + 1) + '/5 · ' + it.r.kind + '</div>'
          + '<div class="mt4" style="font-weight:600">' + it.r.title + '</div>'
          + '<div class="read-body mt8" style="font-size:.92em">' + it.r.paras.map(function (p) { return '<p class="mt4">' + p + '</p>'; }).join('') + '</div>'
          + '<div class="mt8 q-sentence">' + q.q + '</div>'
        : '<div class="label">Soal ' + (i + 1) + '/' + state.items.length + '</div>'
          + '<div class="mt8 q-sentence">' + q.q + '</div>';
      return '<div class="card mt12" data-i="' + i + '">' + head
        + '<div class="opts mt8">' + it.order.map(function (orig, oi) {
            return '<button type="button" class="btn btn-outline btn-block read-opt" data-o="' + oi + '" style="text-align:left">' + q.opts[orig] + '</button>';
          }).join('') + '</div>'
        + '<div class="feedback mt8" hidden></div></div>';
    }).join('');
    quiz.querySelectorAll('[data-i]').forEach(function (card) {
      card.querySelectorAll('[data-o]').forEach(function (btn) {
        btn.addEventListener('click', function () { answer(+card.getAttribute('data-i'), +btn.getAttribute('data-o')); });
      });
    });
    updateScore();
  }

  function answer(i, o) {
    if (!state || state.answered[i] !== undefined) return; // 1 soal hanya 1x jawab
    state.answered[i] = o;
    var it = state.items[i];
    var q = it.r.qs[it.qi];
    var correct = o === it.correct;
    if (correct) state.score++;
    var card = el('readQuiz').querySelector('[data-i="' + i + '"]');
    card.querySelectorAll('[data-o]').forEach(function (b, oi) {
      b.disabled = true;
      if (oi === it.correct) { b.style.borderColor = '#16a34a'; b.style.background = '#dcfce7'; b.style.color = '#166534'; }
      else if (oi === o) { b.style.borderColor = '#dc2626'; b.style.background = '#fee2e2'; b.style.color = '#991b1b'; }
      else { b.style.opacity = '.55'; }
    });
    var fb = card.querySelector('.feedback');
    fb.hidden = false;
    fb.innerHTML = correct
      ? '<div class="tag" style="background:#dcfce7;color:#166534">✅ Benar!</div><p class="small muted mt4">' + q.d + '</p>'
      : '<div class="tag" style="background:#fee2e2;color:#991b1b">❌ Salah — jawaban benar: ' + q.opts[q.a] + '</div><p class="small muted mt4">' + q.d + '</p>';
    updateScore();
    if (Object.keys(state.answered).length === state.items.length) showSummary();
  }

  function updateScore() {
    var t = el('readScoreTag');
    if (t && state) t.textContent = 'Skor: ' + state.score + '/' + state.items.length;
  }

  function showSummary() {
    var n = state.items.length;
    var pct = Math.round((state.score / n) * 100);
    var done = document.createElement('div');
    done.className = 'card tint mt16 read-done';
    var extra = state.mode === 'session'
      ? '<button type="button" class="btn btn-primary btn-block mt8" id="readNewSession">🎲 Sesi baru (5 soal acak lagi)</button>'
      : '<button type="button" class="btn btn-outline btn-block mt8" id="readRetry">↻ Ulangi bacaan ini</button>';
    done.innerHTML = '<div class="label">' + (state.mode === 'session' ? 'Sesi selesai 🎉' : 'Bacaan selesai 🎉') + '</div>'
      + '<div class="big mt4">' + state.score + '/' + n + ' benar (' + pct + '%)</div>' + extra;
    el('readQuiz').appendChild(done);
    var ns = el('readNewSession');
    if (ns) ns.addEventListener('click', startSession);
    var rt = el('readRetry');
    if (rt) rt.addEventListener('click', function () { openReading(state.items[0].r.id); });
  }

  function backToMenu() {
    el('readView').hidden = true;
    el('readMenu').hidden = false;
    window.scrollTo(0, 0);
  }

  function init() {
    if (!el('readList')) return;
    renderMenu();
    var back = el('readBack');
    if (back) back.addEventListener('click', backToMenu);
  }

  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
